
/* ── js/core/field-classifier.js ── */

/**
 * Field Classifier — Shared semantic field-type detection and validation.
 *
 * Maps arbitrary user-given column names to canonical semantic categories
 * (phone, email, name, address, date, blood_group, etc.) using regex patterns.
 * Mirrors the Python classify_column() in exports/column_spec.py.
 *
 * Usage:
 *   FieldClassifier.classify('FATHER MOBILE', 'text')   → 'phone'
 *   FieldClassifier.classify('DOB', 'text')              → 'date'
 *   FieldClassifier.validate('EMAIL', 'text', 'abc')     → { valid: false, message: '…' }
 *
 * @global {Object} window.FieldClassifier
 */
(function () {
'use strict';

var FC = {};

// ── Normalise field name (strip separators, collapse spaces, lowercase) ──
function _norm(name) {
    if (!name) return '';
    return name.trim()
        .replace(/[_.\-'"()\/]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

/**
 * Classify a field name + type into a canonical semantic category.
 *
 * Categories returned:
 *   sr_no, blood_group, age, gender, relationship, class_section,
 *   date, phone, email, id_number, name, address, address_sub,
 *   pincode, short_text, org_text, image, text (default)
 */
FC.classify = function (fieldName, fieldType) {
    var t = (fieldType || '').toLowerCase().trim();

    // ── Explicit type shortcuts ──────────────────────────────────────────
    if (t === 'date')                                         return 'date';
    if (t === 'textarea')                                     return 'address';
    if (t === 'email')                                        return 'email';
    if (['photo','image','mother_photo','father_photo',
         'signature','barcode','qr_code','qr','file'].indexOf(t) >= 0) return 'image';

    var n = _norm(fieldName);
    if (!n) return 'text';

    // ── Serial / row ─────────────────────────────────────────────────────
    if (/^sr\s*no|^s\s*no|^sl\s*no|^serial|^sno$|^slno$/.test(n)) return 'sr_no';

    // ── Blood Group (before name patterns) ───────────────────────────────
    if (/blo?o?d\s*gr|blo?o?d\s*gro?u?p|^bg$|^bgroup$|^b\.?g\.?$|^bld\s*gr|^blud|^blod|blo+d\s*grp|b\s*grp/.test(n)) return 'blood_group';

    // ── Age ──────────────────────────────────────────────────────────────
    if (/^age$|^umar$/.test(n)) return 'age';

    // ── Gender ───────────────────────────────────────────────────────────
    if (/^gender$|^sex$|^gndr$|^gendr$/.test(n)) return 'gender';

    // ── Relationship ─────────────────────────────────────────────────────
    if (/^rel\s*\d*$|^relati?v|^relati?o?n/.test(n)) return 'relationship';

    // ── Class / Section / House ──────────────────────────────────────────
    if (/class.*sec|^class$|^section$|^sec$|^div$|^division$|^cls$|school\s*house|house\s*nam|house\s*col/.test(n)) return 'class_section';

    // ── Dates ────────────────────────────────────────────────────────────
    if (/d\.?\s*o\.?\s*b\.?|date\s*of\s*birth|birth\s*date|b\.?date/.test(n)) return 'date';
    if (/date\s*of\s*join|join(ing)?\s*date|d\.?o\.?j\.?|join\s*dt/.test(n)) return 'date';
    if (/valid\s*(from|till|upto)|validity|expiry|expire/.test(n))            return 'date';
    if (/\bdate\b|\bdt\b/.test(n))                                           return 'date';

    // ── Parent/guardian phone (BEFORE name patterns) ─────────────────────
    if (/(?:father|mother|guardian|parent|mama|nana|dada|nani|dadi)\s*(?:no\.?|num|mob|ph(?:one)?|cell|tel|contact)/.test(n)) return 'phone';

    // ── Driver phone ─────────────────────────────────────────────────────
    if (/driver\s*(?:no\b|numb?\w*|mob|pho?ne?|cell|contact|tel)/.test(n)) return 'phone';

    // ── Phone / Mobile ───────────────────────────────────────────────────
    if (/mobi?le?|pho?ne?|cell\b|tel\b|whatsapp|^mob\b|^ph\b|fone|contact\s*no|contact\s*num|emergency\s*contact\s*num|office\s*contact|alternate\s*mob|alt\s*mob/.test(n)) return 'phone';

    // ── Email ────────────────────────────────────────────────────────────
    if (/e?\s*mail|mail\s*id/.test(n)) return 'email';

    // ── ID Documents ─────────────────────────────────────────────────────
    if (/a+dh?a+r|a+dhr|uidai|uid\s*no/.test(n))                                    return 'id_number';
    if (/^pan$|pan\s*no|pan\s*num|pan\s*card/.test(n))                                return 'id_number';
    if (/voter\s*id|epic\s*no|votr/.test(n))                                          return 'id_number';
    if (/driv\w*\s*li[cs]?en[cs]?e?|^dl$|dl\s*no|dl\s*num/.test(n))                  return 'id_number';
    if (/passport\s*no|passport\s*num|^ppn$/.test(n))                                 return 'id_number';
    if (/ration\s*card/.test(n))                                                      return 'id_number';
    if (/abha|ayushman|health\s*id/.test(n))                                          return 'id_number';
    if (/esic|\bpf\b|uan\s*no|uan\s*num|\buan\b|\bepf\b/.test(n))                    return 'id_number';

    // ── Generic ID numbers ───────────────────────────────────────────────
    if (/roll\s*no|roll\s*num|^roll$/.test(n))                                        return 'id_number';
    if (/emp\s*code|employee\s*code|emp\s*id|staff\s*id/.test(n))                     return 'id_number';
    if (/admis?si?on\s*(?:no|num)/.test(n))                                           return 'id_number';
    if (/reg\s*no|registra?ti?on|enrol/.test(n))                                      return 'id_number';
    if (/scholar\s*(?:no|num|id|code)?\b|^scholar$/.test(n))                          return 'id_number';
    if (/unique\s*(?:no|num|id|code)|^unique$/.test(n))                               return 'id_number';
    if (/teacher\s*(?:code|id|no)|^sch\s*no$|\bsch\s*no\b|school\s*(?:no|num|id)/.test(n)) return 'id_number';
    if (/id\s*card\s*no|id\s*card\s*num|id\s*no|idno|^id$/.test(n))                  return 'id_number';
    if (/service\s*no|service\s*num/.test(n))                                         return 'id_number';

    // ── Names (after phone + ID patterns) ────────────────────────────────
    if (/husband|wife|spouse/.test(n))                                                return 'name';
    if (/gu?a?rdi?a?n/.test(n))                                                      return 'name';
    if (/fa?the?r|mothe?r|parent|papa|maa|mata|pita/.test(n))                         return 'name';
    if (/full\s*n|first\s*n|middle\s*n|last\s*n|sur\s*n|student\s*n|emp\s*n|employee\s*n|^name$|^nm$|^nme$/.test(n)) return 'name';
    if (/reporting\s*manager|manager\s*n/.test(n))                                    return 'name';
    if (/\bname\b/.test(n))                                                           return 'name';

    // ── Address ──────────────────────────────────────────────────────────
    if (/permane?nt?\s*addr|curre?nt?\s*addr|prese?nt?\s*addr|^address$|^addr|^adre?s/.test(n)) return 'address';
    if (/^city$|^town$|^village$|^vill$/.test(n))   return 'address_sub';
    if (/^district$|^dist$|^distt$/.test(n))         return 'address_sub';
    if (/^state$|^province$/.test(n))                return 'address_sub';
    if (/pin\s*code|^pin$|^zip$|postal\s*code|^pincode$/.test(n)) return 'pincode';
    if (/^country$/.test(n))                         return 'address_sub';

    // ── Nationality / Religion / Caste / Marital ─────────────────────────
    if (/nat[io]+na?li?ty?|^nation$/.test(n))        return 'short_text';
    if (/religi?o?n|^rlgn$/.test(n))                 return 'short_text';
    if (/caste|catego?r?y?|^cat$/.test(n))            return 'short_text';
    if (/marita?l|marri?e?d|unmarri?e?d/.test(n))     return 'short_text';
    if (/\brank\b/.test(n))                           return 'short_text';

    // ── Organisation / Education ─────────────────────────────────────────
    if (/college|^school$|institu|^university$|^branch$|branch\s*name|^depart|^dept$|designa|^course$|^batch$|^semester$|^stream$/.test(n)) return 'org_text';

    // ── Transport ────────────────────────────────────────────────────────
    if (/bus|stop\s*name|route\s*no|route\s*name|driver/.test(n)) return 'short_text';

    // ── Misc ─────────────────────────────────────────────────────────────
    if (/hostel|room\s*no/.test(n))          return 'short_text';
    if (/library|lab\s*access|lab\s*code/.test(n)) return 'short_text';

    return 'text';
};

// ── Alignment helper ─────────────────────────────────────────────────────
// Returns 'center' or 'left' based on category.
FC.align = function (category) {
    switch (category) {
        case 'sr_no':
        case 'blood_group':
        case 'age':
        case 'gender':
        case 'class_section':
        case 'date':
        case 'phone':
        case 'id_number':
        case 'relationship':
        case 'pincode':
        case 'short_text':
            return 'center';
        default:
            return 'left';
    }
};

// ── Width+Alignment CSS class helper (for table <td>) ────────────────────
// Returns a complete Tailwind class string for a field cell.
FC.tdClass = function (fieldName, fieldType) {
    var cat = FC.classify(fieldName, fieldType);
    switch (cat) {
        case 'sr_no':        return 'w-[36px] text-center whitespace-nowrap';
        case 'age':          return 'w-[38px] text-center whitespace-nowrap';
        case 'gender':       return 'w-[45px] text-center whitespace-nowrap';
        case 'blood_group':  return 'w-[45px] text-center whitespace-nowrap';
        case 'class_section':return 'w-[52px] text-center whitespace-nowrap';
        case 'date':         return 'w-[80px] text-center whitespace-nowrap';
        case 'relationship': return 'min-w-[62px] max-w-[120px] text-center whitespace-normal break-words';
        case 'phone':        return 'min-w-[120px] text-center whitespace-nowrap phone-col';
        case 'email':        return 'min-w-[130px] max-w-[200px] text-left whitespace-normal break-words email-col';
        case 'id_number':    return 'min-w-[90px] text-center whitespace-nowrap';
        case 'name':         return 'min-w-[100px] text-left whitespace-normal break-words';
        case 'address':      return 'min-w-[130px] max-w-[220px] text-left whitespace-normal break-words address-col';
        case 'address_sub':  return 'min-w-[70px] text-left whitespace-normal break-words';
        case 'pincode':      return 'w-[60px] text-center whitespace-nowrap';
        case 'short_text':   return 'min-w-[60px] text-center whitespace-normal break-words';
        case 'org_text':     return 'min-w-[80px] text-center whitespace-normal break-words';
        default:             return 'min-w-[80px] text-left whitespace-normal break-words';
    }
};

// ── Truncate username for display ────────────────────────────────────────
FC.truncateUser = function (username, maxLen) {
    if (!username) return '';
    maxLen = maxLen || 7;
    username = username.trim();
    if (username.length <= maxLen) return username;
    return username.substring(0, maxLen) + '..';
};

// ── Basic field validation (for inline edit + add/edit modal) ────────────
// Returns { valid: true } or { valid: false, message: '…' }
// Empty values are always valid (not required validation).
FC.validate = function (fieldName, fieldType, value) {
    if (!value || !value.trim()) return { valid: true };
    var cat = FC.classify(fieldName, fieldType);
    var v = value.trim();

    switch (cat) {
        case 'email':
            if (v.indexOf('@') === -1)
                return { valid: false, message: 'Email should contain @' };
            if (v.indexOf('.') === -1)
                return { valid: false, message: 'Email should contain a domain (e.g. @gmail.com)' };
            break;

    }
    return { valid: true };
};

window.FieldClassifier = FC;
})();


/* ── js/core/api.js ── */

/**
 * Core API Module
 * Single API wrapper — every fetch call in the app routes through here.
 *
 * Provides:
 *   ApiClient.get(url, options)
 *   ApiClient.post(url, data, options)
 *   ApiClient.put(url, data, options)
 *   ApiClient.delete(url, data, options)
 *   ApiClient.upload(url, formData, options)
 *   ApiClient.download(url, method, data, options)
 *   ApiClient.downloadBlob(blob, filename)
 *   ApiClient.downloadBase64(b64, filename, mime)
 *   ApiClient.getCSRFToken()
 *
 * Centralises: CSRF handling, JSON parsing, error formatting, toast display.
 *
 * @module core/api
 * @version 3.0.0
 */

/* ================================================
   GLOBAL 403/401 FETCH INTERCEPTOR
   Catches permission-denied and expired-session responses
   from ALL fetch() calls and handles them appropriately.
   ================================================ */
(function () {
    'use strict';
    var _originalFetch = window.fetch;

    /** True when the current page is the login page itself. */
    var _isLoginPage = window.location.pathname.indexOf('/auth/login') !== -1;

    window.fetch = function () {
        return _originalFetch.apply(this, arguments).then(function (response) {
            // ── Redirect detection ──
            // If the server redirected (302 → login page) and we're NOT
            // already on the login page, the session is expired/invalid.
            if (response.redirected && !_isLoginPage) {
                var finalUrl = response.url || '';
                if (finalUrl.indexOf('/auth/login') !== -1 || finalUrl.indexOf('/login') !== -1) {
                    window.location.href = '/auth/login/';
                    // Return a synthetic "session expired" JSON so callers
                    // don't fail with a JSON-parse error on the HTML body.
                    return new Response(JSON.stringify({
                        success: false,
                        message: 'Session expired. Redirecting to login…'
                    }), {
                        status: 401,
                        headers: { 'Content-Type': 'application/json' }
                    });
                }
            }

            if (response.status === 401) {
                // Session expired (e.g., logged out in another tab)
                response.clone().json()
                    .then(function (data) {
                        if (data && data.redirect) {
                            window.location.href = data.redirect;
                        } else {
                            window.location.href = '/auth/login/';
                        }
                    })
                    .catch(function () {
                        window.location.href = '/auth/login/';
                    });
            }
            if (response.status === 403) {
                response.clone().json()
                    .then(function (data) {
                        var msg = (data && data.message) || 'Permission denied';
                        if (typeof window.showToast === 'function') {
                            window.showToast(msg, 'error', 5000);
                        }
                    })
                    .catch(function () {
                        if (typeof window.showToast === 'function') {
                            window.showToast('Permission denied', 'error', 5000);
                        }
                    });
            }
            return response;
        });
    };
})();

/* ================================================
   ApiClient — the single authority for network IO
   ================================================ */
(function () {
    'use strict';

    // ------------------------------------------
    // CSRF TOKEN
    // ------------------------------------------
    function getCSRFToken() {
        var cookie = document.cookie.split(';').find(function (c) {
            return c.trim().startsWith('csrftoken=');
        });
        if (cookie) return cookie.split('=')[1];

        var meta = document.querySelector('meta[name="csrf-token"]');
        if (meta) return meta.getAttribute('content');

        var hidden = document.querySelector('input[name="csrfmiddlewaretoken"]');
        if (hidden) return hidden.value;

        return '';
    }

    // ------------------------------------------
    // DEFAULTS
    // ------------------------------------------
    var DEFAULTS = { timeout: 30000, retries: 0, retryDelay: 1000 };

    // ------------------------------------------
    // LOW-LEVEL FETCH WRAPPER
    // ------------------------------------------
    async function _request(url, method, data, options) {
        // Safeguard: block requests to external origins (prevents credential leaking)
        if (url.indexOf('://') !== -1 && url.indexOf(window.location.origin) !== 0) {
            return Promise.reject(new Error('API request blocked: external URL not allowed'));
        }

        var config = Object.assign({}, DEFAULTS, options);

        var headers = Object.assign({
            'Content-Type': 'application/json',
            'X-CSRFToken': getCSRFToken(),
            'X-Requested-With': 'XMLHttpRequest'
        }, config.headers || {});

        var fetchOpts = { method: method.toUpperCase(), headers: headers };

        if (data && method.toUpperCase() !== 'GET') {
            fetchOpts.body = JSON.stringify(data);
        }

        var controller = new AbortController();
        var tid = setTimeout(function () { controller.abort(); }, config.timeout);
        fetchOpts.signal = controller.signal;

        var lastError;
        var attempts = 0;
        var maxAttempts = config.retries + 1;

        while (attempts < maxAttempts) {
            try {
                var response = await fetch(url, fetchOpts);
                clearTimeout(tid);

                var ct = response.headers.get('content-type');
                var body;
                if (ct && ct.indexOf('application/json') !== -1) {
                    body = await response.json();
                } else {
                    body = await response.text();
                }

                if (!response.ok) {
                    var msg = (response.status === 403)
                        ? ((body && body.message) || 'Permission denied')
                        : ((body && body.message) || 'HTTP ' + response.status);
                    var err = new Error(msg);
                    err.status = response.status;
                    err.data = body;
                    throw err;
                }
                return body;

            } catch (error) {
                lastError = error;
                attempts++;
                if (error.name === 'AbortError') {
                    lastError = new Error('Request timeout');
                    lastError.code = 'TIMEOUT';
                    break;
                }
                if (attempts < maxAttempts) {
                    await new Promise(function (r) { setTimeout(r, config.retryDelay); });
                }
            }
        }

        // Show toast only for true network/timeout errors, NOT for API errors
        // (API errors like 400/403 are handled by the caller)
        if (typeof window.showToast === 'function' && !lastError.status) {
            window.showToast(lastError.message || 'Network error', 'error');
        }
        throw lastError;
    }

    // ------------------------------------------
    // UPLOAD (FormData + XHR for progress)
    // ------------------------------------------
    function _upload(url, formData, options) {
        options = options || {};
        return new Promise(function (resolve, reject) {
            var xhr = new XMLHttpRequest();
            xhr.open('POST', url, true);
            xhr.setRequestHeader('X-CSRFToken', getCSRFToken());
            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');

            if (options.onProgress) {
                xhr.upload.onprogress = function (e) {
                    if (e.lengthComputable) {
                        options.onProgress(Math.round((e.loaded / e.total) * 100), e.loaded, e.total);
                    }
                };
            }

            xhr.onload = function () {
                try {
                    var resp = JSON.parse(xhr.responseText);
                    if (xhr.status >= 200 && xhr.status < 300) { resolve(resp); }
                    else { reject({ status: xhr.status, data: resp }); }
                } catch (_e) {
                    if (xhr.status >= 200 && xhr.status < 300) { resolve(xhr.responseText); }
                    else { reject({ status: xhr.status, message: 'Failed to parse response' }); }
                }
            };
            xhr.onerror = function () { reject({ message: 'Network error' }); };
            xhr.ontimeout = function () { reject({ message: 'Request timeout', code: 'TIMEOUT' }); };

            if (options.timeout) xhr.timeout = options.timeout;
            xhr.send(formData);
        });
    }

    // ------------------------------------------
    // DOWNLOAD (XHR with progress → Blob)
    // ------------------------------------------
    function _download(url, method, data, options) {
        method = method || 'GET';
        options = options || {};
        return new Promise(function (resolve, reject) {
            var xhr = new XMLHttpRequest();
            xhr.open(method, url, true);
            xhr.setRequestHeader('X-CSRFToken', getCSRFToken());
            if (data) xhr.setRequestHeader('Content-Type', 'application/json');
            xhr.responseType = 'blob';

            if (options.onProgress) {
                xhr.onprogress = function (e) {
                    if (e.lengthComputable) {
                        options.onProgress(Math.round((e.loaded / e.total) * 100), e.loaded, e.total);
                    }
                };
            }

            xhr.onload = function () {
                if (xhr.status >= 200 && xhr.status < 300) { resolve(xhr.response); }
                else { reject({ status: xhr.status, message: 'HTTP ' + xhr.status }); }
            };
            xhr.onerror = function () { reject({ message: 'Network error' }); };
            xhr.send(data ? JSON.stringify(data) : null);
        });
    }

    // ------------------------------------------
    // BLOB / BASE64 HELPERS
    // ------------------------------------------
    function downloadBlob(blob, filename) {
        var u = window.URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.style.display = 'none';
        a.href = u;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(u);
        document.body.removeChild(a);
    }

    function downloadBase64(b64, filename, mime) {
        mime = mime || 'application/octet-stream';
        var bin = atob(b64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        downloadBlob(new Blob([bytes], { type: mime }), filename);
    }

    // ------------------------------------------
    // PUBLIC CLASS
    // ------------------------------------------
    var ApiClient = {
        getCSRFToken: getCSRFToken,

        get: function (url, options)             { return _request(url, 'GET', null, options); },
        post: function (url, data, options)      { return _request(url, 'POST', data, options); },
        put: function (url, data, options)       { return _request(url, 'PUT', data, options); },
        delete: function (url, data, options)    { return _request(url, 'DELETE', data, options); },

        upload: _upload,
        download: _download,
        downloadBlob: downloadBlob,
        downloadBase64: downloadBase64,

        /** Low-level: any method */
        request: _request
    };

    // ------------------------------------------
    // EXPOSE
    // ------------------------------------------
    window.ApiClient  = ApiClient;

    // Namespaced alias
    window.AdarshAjax = {
        getCSRFToken:   getCSRFToken,
        apiCall:        _request,
        get:            ApiClient.get,
        post:           ApiClient.post,
        put:            ApiClient.put,
        'delete':       ApiClient.delete,
        upload:         _upload,
        download:       _download,
        downloadBlob:   downloadBlob,
        downloadBase64: downloadBase64
    };

    // Legacy globals (backward compat — will be removed)
    window.getCSRFToken = getCSRFToken;
    window.apiCall      = function (url, method, data, options) {
        return _request(url, method || 'GET', data, options);
    };

})();


/* ── js/core/toast.js ── */

/**
 * Core Toast Module
 * Single authority for all toast / notification display.
 *
 * Simple toasts delegate to Alpine's toast queue when available,
 * falling back to DOM-based toast when Alpine has not initialised.
 * Progress / download-complete toasts always use the DOM toast
 * because Alpine does not support a progress-bar variant.
 *
 * Public API:
 *   Toast.success(msg, duration?)
 *   Toast.error(msg, duration?)
 *   Toast.info(msg, duration?)
 *   Toast.warning(msg, duration?)
 *   Toast.progress(msg, percent?)     // percent = -1 → indeterminate
 *   Toast.complete(msg?)
 *   Toast.hide()
 *
 * @module core/toast
 * @version 4.0.0
 */

(function () {
    'use strict';

    // ------------------------------------------
    // STATE
    // ------------------------------------------
    var _toastTimeout    = null;
    var _progressTimeout = null;
    var _progressCancelCb = null;  // cancel callback for progress toast

    // ------------------------------------------
    // ICON MAP
    // ------------------------------------------
    var ICONS = {
        success: 'fa-check-circle',
        error:   'fa-times-circle',
        info:    'fa-info-circle',
        warning: 'fa-exclamation-triangle'
    };

    // ------------------------------------------
    // ENSURE DOM ELEMENT EXISTS (for progress toasts & fallback)
    // ------------------------------------------
    function _ensureEl() {
        var toast = document.getElementById('toast');
        if (toast) return toast;
        toast = document.createElement('div');
        toast.id = 'toast';
        toast.className = 'toast';
        toast.setAttribute('role', 'alert');
        toast.setAttribute('aria-live', 'assertive');
        toast.innerHTML =
            '<i id="toastIcon" class="fa-solid fa-check-circle"></i>' +
            '<span id="toastMessage">Success!</span>' +
            '<span id="toastPercent" style="display:none;margin-left:8px;font-weight:600;"></span>' +
            '<button id="toastCancelBtn" type="button" title="Cancel" ' +
            'style="display:none;background:none;border:none;color:inherit;cursor:pointer;' +
            'margin-left:10px;padding:2px 6px;font-size:1.1em;opacity:.7;transition:opacity .2s;" ' +
            'onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.7">' +
            '<i class="fa-solid fa-xmark"></i></button>' +
            '<div id="toastProgress" class="toast-progress" style="display:none;">' +
            '  <div id="toastProgressBar" class="toast-progress-bar"></div>' +
            '</div>';
        document.body.appendChild(toast);
        // Wire cancel button
        var cancelBtn = document.getElementById('toastCancelBtn');
        if (cancelBtn) {
            cancelBtn.addEventListener('click', function () {
                if (typeof _progressCancelCb === 'function') {
                    _progressCancelCb();
                    _progressCancelCb = null;
                }
                hideToast();
            });
        }
        return toast;
    }

    // ------------------------------------------
    // LOW-LEVEL: showToast
    // Delegates to Alpine when available; falls back to DOM toast
    // ------------------------------------------
    function showToast(message, type, duration) {
        // Normalise type (boolean → string)
        if (typeof type === 'boolean') type = type ? 'success' : 'error';
        type = type || 'success';

        // ---- Alpine bridge (preferred) ----
        if (typeof window.alpineShowToast === 'function') {
            window.alpineShowToast(message, type);
            return;
        }

        // ---- DOM fallback ----
        duration = (duration !== undefined) ? duration : 3000;

        if (_toastTimeout) { clearTimeout(_toastTimeout); _toastTimeout = null; }

        var toast       = _ensureEl();
        var msgEl       = document.getElementById('toastMessage')     || toast.querySelector('span');
        var iconEl      = document.getElementById('toastIcon')        || toast.querySelector('i');
        var progressEl  = document.getElementById('toastProgress');
        var barEl       = document.getElementById('toastProgressBar');

        if (msgEl)  msgEl.textContent = message;
        if (iconEl) iconEl.className  = 'fa-solid ' + (ICONS[type] || ICONS.success);

        if (progressEl) progressEl.style.display = 'none';
        if (barEl) { barEl.classList.remove('indeterminate'); barEl.style.width = '0%'; }
        var cancelBtnSimple = document.getElementById('toastCancelBtn');
        if (cancelBtnSimple) cancelBtnSimple.style.display = 'none';
        _progressCancelCb = null;

        toast.className = 'toast show ' + type;

        _toastTimeout = setTimeout(function () { toast.classList.remove('show'); }, duration);
    }

    // ------------------------------------------
    // PROGRESS TOAST
    // ------------------------------------------
    function showProgressToast(message, progress, onCancel) {
        if (progress === undefined) progress = -1;
        if (_progressTimeout) { clearTimeout(_progressTimeout); _progressTimeout = null; }

        // Store cancel callback
        if (typeof onCancel === 'function') _progressCancelCb = onCancel;

        var toast      = _ensureEl();
        var msgEl      = document.getElementById('toastMessage')      || toast.querySelector('span');
        var iconEl     = document.getElementById('toastIcon')         || toast.querySelector('i');
        var progressEl = document.getElementById('toastProgress');
        var barEl      = document.getElementById('toastProgressBar');
        var pctEl      = document.getElementById('toastPercent');
        var cancelBtn  = document.getElementById('toastCancelBtn');

        if (msgEl)  msgEl.textContent = message;
        if (iconEl) iconEl.className  = 'fa-solid fa-spinner fa-spin';
        if (progressEl) progressEl.style.display = 'block';

        // Show cancel/stop button when a cancel callback is registered
        if (cancelBtn) {
            cancelBtn.style.display = _progressCancelCb ? 'inline-block' : 'none';
        }

        if (msgEl)  msgEl.textContent = message;
        if (iconEl) iconEl.className  = 'fa-solid fa-spinner fa-spin';
        if (progressEl) progressEl.style.display = 'block';

        if (pctEl) {
            if (progress >= 0) {
                pctEl.style.display = 'inline';
                pctEl.textContent   = Math.round(progress) + '%';
            } else {
                pctEl.style.display = 'none';
            }
        }

        if (barEl) {
            if (progress < 0) {
                barEl.classList.add('indeterminate');
                barEl.style.width = '30%';
            } else {
                barEl.classList.remove('indeterminate');
                barEl.style.width = Math.min(progress, 100) + '%';
            }
        }

        toast.className = 'toast show downloading';
    }

    // ------------------------------------------
    // COMPLETE TOAST
    // ------------------------------------------
    function showDownloadComplete(message) {
        message = message || 'Successfully downloaded!';
        if (_progressTimeout) { clearTimeout(_progressTimeout); _progressTimeout = null; }
        _progressCancelCb = null;

        var toast      = _ensureEl();
        var msgEl      = document.getElementById('toastMessage')      || toast.querySelector('span');
        var iconEl     = document.getElementById('toastIcon')         || toast.querySelector('i');
        var progressEl = document.getElementById('toastProgress');
        var barEl      = document.getElementById('toastProgressBar');
        var pctEl      = document.getElementById('toastPercent');
        var cancelBtn  = document.getElementById('toastCancelBtn');

        if (msgEl)  msgEl.textContent = message;
        if (iconEl) iconEl.className  = 'fa-solid fa-check-circle';
        if (progressEl) progressEl.style.display = 'block';
        if (barEl)  { barEl.classList.remove('indeterminate'); barEl.style.width = '100%'; }
        if (pctEl)  { pctEl.style.display = 'inline'; pctEl.textContent = '100%'; }
        if (cancelBtn) cancelBtn.style.display = 'none';

        toast.className = 'toast show success';

        _progressTimeout = setTimeout(function () {
            toast.classList.remove('show');
            if (progressEl) progressEl.style.display = 'none';
            if (barEl) barEl.style.width = '0%';
        }, 3000);
    }

    // ------------------------------------------
    // HIDE
    // ------------------------------------------
    function hideToast() {
        var toast = document.getElementById('toast');
        if (toast) toast.classList.remove('show');
        if (_toastTimeout)    { clearTimeout(_toastTimeout);    _toastTimeout    = null; }
        if (_progressTimeout) { clearTimeout(_progressTimeout); _progressTimeout = null; }
        _progressCancelCb = null;
        var cancelBtn = document.getElementById('toastCancelBtn');
        if (cancelBtn) cancelBtn.style.display = 'none';
    }

    // ------------------------------------------
    // PUBLIC CLASS
    // ------------------------------------------
    var Toast = {
        success:  function (msg, dur) { showToast(msg, 'success', dur); },
        error:    function (msg, dur) { showToast(msg, 'error',   dur); },
        info:     function (msg, dur) { showToast(msg, 'info',    dur); },
        warning:  function (msg, dur) { showToast(msg, 'warning', dur); },
        progress: showProgressToast,
        complete: showDownloadComplete,
        hide:     hideToast
    };

    // ------------------------------------------
    // EXPOSE
    // ------------------------------------------
    window.Toast = Toast;

    // Namespaced alias
    window.AdarshToast = {
        show:         showToast,
        showProgress: showProgressToast,
        showComplete: showDownloadComplete,
        hide:         hideToast
    };

    // Legacy globals
    window.showToast            = showToast;
    window.showProgressToast    = showProgressToast;
    window.showDownloadComplete = showDownloadComplete;
    window.hideToast            = hideToast;
    window.hideProgressToast    = hideToast;

})();


/* ── js/core/confirm.js ── */

/**
 * Core Confirm Module
 * Universal confirmation modal that works on every page.
 * Dynamically creates DOM + styles on first use.
 *
 * Public API:
 *   showConfirm(opts)  → Promise<boolean>
 *
 * Options:
 *   title        {string}   – Modal title (default: 'Are you sure?')
 *   text         {string}   – Description text (default: 'This action cannot be undone.')
 *   icon         {string}   – FontAwesome class (default: 'fa-solid fa-triangle-exclamation')
 *   confirmLabel {string}   – Confirm button text (default: 'Confirm')
 *   cancelLabel  {string}   – Cancel button text  (default: 'Cancel')
 *   btnClass     {string}   – Confirm button class (default: 'btn-danger')
 *   warnings     {string[]} – Warning bullet list items
 *   hideWarning  {boolean}  – Hide the warning box entirely
 *
 * @module core/confirm
 * @version 1.0.0
 */
(function () {
  'use strict';

  var OVERLAY_ID  = 'coreConfirmOverlay';
  var _injected   = false;

  /* ── CSS (injected once) ─────────────────────────────────────────── */
  var CSS = [
    '#' + OVERLAY_ID + '{display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);backdrop-filter:blur(3px);z-index:9999;align-items:center;justify-content:center}',
    '#' + OVERLAY_ID + '.show{display:flex}',
    '.cc-box{background:#fff;border-radius:10px;box-shadow:0 12px 32px rgba(0,0,0,.18),0 2px 6px rgba(0,0,0,.08);width:420px;max-width:95vw;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;animation:ccSlide .15s ease}',
    '@keyframes ccSlide{from{opacity:0;transform:translateY(-12px)}to{opacity:1;transform:translateY(0)}}',
    '.cc-content{flex:1;min-height:0;overflow-y:auto;padding:28px 24px 16px;text-align:center}',
    '.cc-actions{display:flex;gap:8px;justify-content:center;padding:14px 24px 18px;border-top:1px solid #e5e7eb;background:#fafafa;border-radius:0 0 10px 10px;flex-shrink:0}',
    '.cc-actions .btn{min-width:90px}',
    '.cc-icon{display:flex;align-items:center;justify-content:center;width:48px;height:48px;border-radius:50%;margin:0 auto 12px;font-size:20px;background:#fef3c7;color:#d97706}',
    '.cc-title{font-size:15px;font-weight:700;color:#1f2937;margin:0 0 4px}',
    '.cc-text{font-size:13px;color:#6b7280;margin:0 0 10px;line-height:1.5}',
    '.cc-warning{width:100%;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:10px 14px;text-align:left;margin-bottom:16px}',
    '.cc-warning-title{font-size:12px;color:#991b1b;font-weight:600;margin:0 0 6px;display:flex;align-items:center;gap:6px}',
    '.cc-warning-list{margin:0;padding:0 0 0 16px;font-size:12px;color:#7f1d1d;line-height:1.7}'
  ].join('\n');

  /* ── Ensure DOM + CSS exist ──────────────────────────────────────── */
  function ensureDOM() {
    if (_injected) return;
    _injected = true;

    // Inject CSS
    var style = document.createElement('style');
    style.textContent = CSS;
    document.head.appendChild(style);

    // Inject overlay
    var overlay = document.createElement('div');
    overlay.id = OVERLAY_ID;
    overlay.innerHTML =
      '<div class="cc-box">' +
        '<div class="cc-content">' +
          '<div class="cc-icon" id="ccIcon"><i class="fa-solid fa-triangle-exclamation"></i></div>' +
          '<h4 class="cc-title" id="ccTitle">Are you sure?</h4>' +
          '<p class="cc-text" id="ccText">This action cannot be undone.</p>' +
          '<div class="cc-warning" id="ccWarning">' +
            '<p class="cc-warning-title"><i class="fa-solid fa-circle-exclamation"></i> Warning</p>' +
            '<ul class="cc-warning-list" id="ccWarningList">' +
              '<li>This action may affect your data</li>' +
              '<li>Please confirm before proceeding</li>' +
            '</ul>' +
          '</div>' +
        '</div>' +
        '<div class="cc-actions">' +
          '<button type="button" class="btn btn-neutral" id="ccCancel"><i class="fa-solid fa-xmark"></i> Cancel</button>' +
          '<button type="button" class="btn btn-danger" id="ccOk"><i class="fa-solid fa-check"></i> Confirm</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(overlay);
  }

  /* ── Public: showConfirm(opts) → Promise<boolean> ────────────────── */
  function showConfirm(opts) {
    opts = opts || {};

    // Delegate to waConfirm if it exists (website admin pages already have a styled one)
    if (window.waConfirm && document.getElementById('waConfirmOverlay')) {
      return window.waConfirm(opts);
    }

    ensureDOM();

    return new Promise(function (resolve) {
      var overlay     = document.getElementById(OVERLAY_ID);
      var iconEl      = document.getElementById('ccIcon');
      var titleEl     = document.getElementById('ccTitle');
      var textEl      = document.getElementById('ccText');
      var okBtn       = document.getElementById('ccOk');
      var cancelBtn   = document.getElementById('ccCancel');
      var warningBox  = document.getElementById('ccWarning');
      var warningList = document.getElementById('ccWarningList');

      titleEl.textContent = opts.title || 'Are you sure?';
      textEl.textContent  = opts.text  || 'This action cannot be undone.';
      okBtn.innerHTML     = '<i class="fa-solid fa-check"></i> ' + (opts.confirmLabel || 'Confirm');
      cancelBtn.innerHTML = '<i class="fa-solid fa-xmark"></i> ' + (opts.cancelLabel || 'Cancel');
      okBtn.className     = 'btn ' + (opts.btnClass || 'btn-danger');

      if (opts.icon) {
        iconEl.innerHTML = '<i class="' + opts.icon + '"></i>';
      } else {
        iconEl.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i>';
      }

      if (opts.warnings && opts.warnings.length) {
        warningList.innerHTML = opts.warnings.map(function (w) { return '<li>' + w + '</li>'; }).join('');
        warningBox.style.display = '';
      } else if (opts.hideWarning) {
        warningBox.style.display = 'none';
      } else {
        warningList.innerHTML = '<li>This action may affect your data</li><li>Please confirm before proceeding</li>';
        warningBox.style.display = '';
      }

      overlay.classList.add('show');
      okBtn.focus();

      function cleanup(result) {
        overlay.classList.remove('show');
        okBtn.removeEventListener('click', onOk);
        cancelBtn.removeEventListener('click', onCancel);
        overlay.removeEventListener('click', onBackdrop);
        document.removeEventListener('keydown', onEscape);
        resolve(result);
      }
      function onOk()      { cleanup(true);  }
      function onCancel()  { cleanup(false); }
      function onBackdrop(e) { if (e.target === overlay) cleanup(false); }
      function onEscape(e)   { if (e.key === 'Escape') cleanup(false); }

      okBtn.addEventListener('click', onOk);
      cancelBtn.addEventListener('click', onCancel);
      overlay.addEventListener('click', onBackdrop);
      document.addEventListener('keydown', onEscape);
    });
  }

  // Expose globally
  window.showConfirm = showConfirm;

})();


/* ── js/core/modal.js ── */

/**
 * Core Modal Module
 * Single authority for every modal / drawer in the application.
 *
 * Rules enforced by this module:
 *   • Overlay click does NOT close (only close-button or Escape).
 *   • Escape closes the topmost open modal / drawer.
 *   • No duplicate listeners — each modal is registered once.
 *   • Body scroll is locked while any modal / drawer is open.
 *
 * Public API:
 *   ModalManager.open(id, data?)
 *   ModalManager.close(id)
 *   ModalManager.closeAll()
 *   ModalManager.register(id, options?)  — auto-called by open() if needed
 *   ModalManager.isOpen(id)
 *   ModalManager.get(id)
 *
 * Low-level (for advanced pages):
 *   new ModalController(id, options)
 *   new DrawerController(id, options)
 *
 * @module core/modal
 * @version 3.0.0
 */

(function () {
    'use strict';

    // ==========================================
    // REGISTRIES
    // ==========================================
    var modalRegistry  = new Map();
    var drawerRegistry = new Map();

    // ==========================================
    // FOCUS TRAP HELPER (a11y)
    // ==========================================
    var FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

    function _trapFocus(container, e) {
        var focusable = container.querySelectorAll(FOCUSABLE);
        if (!focusable.length) return;
        var first = focusable[0];
        var last  = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) {
            e.preventDefault();
            last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
            e.preventDefault();
            first.focus();
        }
    }

    function _autoFocus(container) {
        var el = container.querySelector('[autofocus]') || container.querySelector(FOCUSABLE);
        if (el) setTimeout(function () { el.focus(); }, 50);
    }

    // ==========================================
    // MODAL CONTROLLER
    // ==========================================
    function ModalController(modalId, options) {
        this.modalId = modalId;
        this.modal   = document.getElementById(modalId);
        this.options = Object.assign({
            overlayClass:       'active',
            lockBodyScroll:     true,
            closeOnOverlayClick: false,   // ← CHANGED from true
            closeOnEscape:      true,
            onOpen:  null,
            onClose: null
        }, options || {});

        this._bound = false;
        this._bindEvents();
        modalRegistry.set(modalId, this);
    }

    ModalController.prototype._bindEvents = function () {
        if (!this.modal || this._bound) return;
        this._bound = true;
        var self = this;

        // Close button(s)
        this.modal.querySelectorAll('[data-modal-close], .modal-close, .close-btn').forEach(function (btn) {
            btn.addEventListener('click', function (e) { e.preventDefault(); self.close(); });
        });

        // Cancel button(s)
        this.modal.querySelectorAll('[data-modal-cancel], .modal-cancel, .cancel-btn').forEach(function (btn) {
            btn.addEventListener('click', function (e) { e.preventDefault(); self.close(); });
        });

        // Overlay click — disabled by default
        if (this.options.closeOnOverlayClick) {
            this.modal.addEventListener('click', function (e) {
                if (e.target === self.modal) self.close();
            });
        }
    };

    ModalController.prototype.open = function (data) {
        if (!this.modal) return false;
        // Save trigger element for focus restore (a11y)
        this._triggerEl = document.activeElement;
        this.modal.classList.add(this.options.overlayClass);
        // Set ARIA dialog attributes (a11y)
        this.modal.setAttribute('role', 'dialog');
        this.modal.setAttribute('aria-modal', 'true');
        if (this.options.lockBodyScroll) document.body.style.overflow = 'hidden';
        if (this.options.onOpen) this.options.onOpen(data);
        this.modal.dispatchEvent(new CustomEvent('modal:open', { detail: data }));
        // Focus trap (a11y)
        var self = this;
        this._focusTrapHandler = function (e) { if (e.key === 'Tab') _trapFocus(self.modal, e); };
        document.addEventListener('keydown', this._focusTrapHandler);
        _autoFocus(this.modal);
        return true;
    };

    ModalController.prototype.close = function () {
        if (!this.modal) return false;
        this.modal.classList.remove(this.options.overlayClass);
        // Remove ARIA and focus trap (a11y)
        this.modal.removeAttribute('aria-modal');
        if (this._focusTrapHandler) {
            document.removeEventListener('keydown', this._focusTrapHandler);
            this._focusTrapHandler = null;
        }
        if (this.options.lockBodyScroll) {
            var anyOpen = false;
            modalRegistry.forEach(function (m) { if (m.isOpen()) anyOpen = true; });
            if (!anyOpen) document.body.style.overflow = '';
        }
        if (this.options.onClose) this.options.onClose();
        this.modal.dispatchEvent(new CustomEvent('modal:close'));
        // Restore focus to trigger element (a11y)
        if (this._triggerEl && typeof this._triggerEl.focus === 'function') {
            this._triggerEl.focus();
            this._triggerEl = null;
        }
        return true;
    };

    ModalController.prototype.isOpen = function () {
        return this.modal ? this.modal.classList.contains(this.options.overlayClass) : false;
    };

    ModalController.prototype.toggle = function () {
        return this.isOpen() ? this.close() : this.open();
    };

    // ==========================================
    // DRAWER CONTROLLER
    // ==========================================
    function DrawerController(drawerId, options) {
        this.drawerId = drawerId;
        this.drawer   = document.getElementById(drawerId);
        options = options || {};
        this.overlay  = document.getElementById(drawerId + '-overlay') ||
                        document.getElementById(options.overlayId || '');
        this.options  = Object.assign({
            openClass:           'open',
            overlayActiveClass:  'active',
            lockBodyScroll:      true,
            closeOnOverlayClick: false,   // ← CHANGED from true
            closeOnEscape:       true,
            onOpen:  null,
            onClose: null,
            onModeChange: null,
            modes: {
                add:  { icon: 'fa-plus',          title: 'Add New', submitText: 'Add' },
                edit: { icon: 'fa-pen-to-square',  title: 'Edit',    submitText: 'Save Changes' },
                view: { icon: 'fa-eye',            title: 'View',    submitText: null }
            }
        }, options);

        this.currentMode = 'add';
        this.currentData = null;

        this._cacheElements();
        this._bound = false;
        this._bindEvents();
        drawerRegistry.set(drawerId, this);
    }

    DrawerController.prototype._cacheElements = function () {
        if (!this.drawer) return;
        this.elements = {
            closeBtn:  this.drawer.querySelector('[data-drawer-close], .drawer-close, .close-btn'),
            cancelBtn: this.drawer.querySelector('[data-drawer-cancel], .drawer-cancel, .cancel-btn'),
            submitBtn: this.drawer.querySelector('[data-drawer-submit], .drawer-submit, [type="submit"]'),
            title:     this.drawer.querySelector('[data-drawer-title], .drawer-title span'),
            icon:      this.drawer.querySelector('[data-drawer-icon], .drawer-title i'),
            form:      this.drawer.querySelector('form')
        };
    };

    DrawerController.prototype._bindEvents = function () {
        if (!this.drawer || this._bound) return;
        this._bound = true;
        var self = this;

        if (this.elements.closeBtn) {
            this.elements.closeBtn.addEventListener('click', function (e) { e.preventDefault(); self.close(); });
        }
        if (this.elements.cancelBtn) {
            this.elements.cancelBtn.addEventListener('click', function (e) { e.preventDefault(); self.close(); });
        }
        if (this.overlay && this.options.closeOnOverlayClick) {
            this.overlay.addEventListener('click', function () { self.close(); });
        }
    };

    DrawerController.prototype.open = function (mode, data) {
        if (!this.drawer) return false;
        mode = mode || 'add';
        this.currentMode = mode;
        this.currentData = data || null;
        // Save trigger element for focus restore (a11y)
        this._triggerEl = document.activeElement;

        var cfg = this.options.modes[mode] || this.options.modes.add;

        if (this.elements.icon) this.elements.icon.className = 'fa-solid ' + cfg.icon;

        if (this.elements.submitBtn) {
            if (cfg.submitText) {
                this.elements.submitBtn.style.display = '';
                var txt = this.elements.submitBtn.querySelector('span') || this.elements.submitBtn;
                if (txt.tagName !== 'I') txt.textContent = cfg.submitText;
            } else {
                this.elements.submitBtn.style.display = 'none';
            }
        }

        this.drawer.classList.add(this.options.openClass);
        if (this.overlay) this.overlay.classList.add(this.options.overlayActiveClass);
        if (this.options.lockBodyScroll) document.body.style.overflow = 'hidden';
        // Set ARIA dialog attributes (a11y)
        this.drawer.setAttribute('role', 'dialog');
        this.drawer.setAttribute('aria-modal', 'true');
        if (this.options.onModeChange) this.options.onModeChange(mode);
        if (this.options.onOpen) this.options.onOpen(mode, data);
        this.drawer.dispatchEvent(new CustomEvent('drawer:open', { detail: { mode: mode, data: data } }));
        // Focus trap (a11y)
        var self = this;
        this._focusTrapHandler = function (e) { if (e.key === 'Tab') _trapFocus(self.drawer, e); };
        document.addEventListener('keydown', this._focusTrapHandler);
        _autoFocus(this.drawer);
        return true;
    };

    DrawerController.prototype.close = function () {
        if (!this.drawer) return false;
        this.drawer.classList.remove(this.options.openClass);
        if (this.overlay) this.overlay.classList.remove(this.options.overlayActiveClass);
        // Remove ARIA and focus trap (a11y)
        this.drawer.removeAttribute('aria-modal');
        if (this._focusTrapHandler) {
            document.removeEventListener('keydown', this._focusTrapHandler);
            this._focusTrapHandler = null;
        }
        if (this.options.lockBodyScroll) {
            var anyOpen = false;
            drawerRegistry.forEach(function (d) { if (d.isOpen()) anyOpen = true; });
            if (!anyOpen) document.body.style.overflow = '';
        }
        if (this.options.onClose) this.options.onClose();
        this.drawer.dispatchEvent(new CustomEvent('drawer:close'));
        // Restore focus to trigger element (a11y)
        if (this._triggerEl && typeof this._triggerEl.focus === 'function') {
            this._triggerEl.focus();
            this._triggerEl = null;
        }
        return true;
    };

    DrawerController.prototype.isOpen = function () {
        return this.drawer ? this.drawer.classList.contains(this.options.openClass) : false;
    };

    DrawerController.prototype.setTitle = function (title) {
        if (this.elements.title) this.elements.title.textContent = title;
    };

    DrawerController.prototype.setSubmitText = function (text) {
        if (this.elements.submitBtn) {
            var t = this.elements.submitBtn.querySelector('span') || this.elements.submitBtn;
            t.textContent = text;
        }
    };

    DrawerController.prototype.setLoading = function (loading) {
        if (!this.elements.submitBtn) return;
        this.elements.submitBtn.disabled = loading;
        var icon = this.elements.submitBtn.querySelector('i');
        if (icon) {
            if (loading) {
                icon.dataset.originalClass = icon.className;
                icon.className = 'fa-solid fa-spinner fa-spin';
            } else if (icon.dataset.originalClass) {
                icon.className = icon.dataset.originalClass;
            }
        }
    };

    DrawerController.prototype.resetForm = function () {
        if (this.elements.form) this.elements.form.reset();
    };

    DrawerController.prototype.enableInputs = function (enabled) {
        if (!this.drawer) return;
        this.drawer.querySelectorAll('input, select, textarea').forEach(function (el) {
            el.disabled = !enabled;
            el.readOnly = !enabled;
        });
    };

    // ==========================================
    // GLOBAL ESCAPE KEY — single listener
    // ==========================================
    document.addEventListener('keydown', function (e) {
        if (e.key !== 'Escape') return;

        // Close modals (most-recent first)
        var entries = Array.from(modalRegistry.entries()).reverse();
        for (var i = 0; i < entries.length; i++) {
            var m = entries[i][1];
            if (m.isOpen() && m.options.closeOnEscape) {
                m.close();
                e.preventDefault();
                return;
            }
        }

        // Then drawers
        var dEntries = Array.from(drawerRegistry.entries()).reverse();
        for (var j = 0; j < dEntries.length; j++) {
            var d = dEntries[j][1];
            if (d.isOpen() && d.options.closeOnEscape) {
                d.close();
                e.preventDefault();
                return;
            }
        }
    });

    // ==========================================
    // ModalManager — high-level façade
    // ==========================================
    function _getOrRegister(id, options) {
        var existing = modalRegistry.get(id) || drawerRegistry.get(id);
        if (existing) return existing;
        // Auto-detect: if element has class "drawer" treat it as drawer
        var el = document.getElementById(id);
        if (!el) return null;
        if (el.classList.contains('drawer') || el.classList.contains('side-drawer')) {
            return new DrawerController(id, options);
        }
        return new ModalController(id, options);
    }

    var ModalManager = {
        /** Register a modal/drawer before first use (optional — open() auto-registers). */
        register: function (id, options) { return _getOrRegister(id, options); },

        /** Open a modal/drawer by element ID. */
        open: function (id, data) {
            var ctrl = _getOrRegister(id);
            if (!ctrl) return false;
            // DrawerController.open accepts (mode, data), ModalController.open accepts (data)
            if (ctrl instanceof DrawerController) return ctrl.open(data);
            return ctrl.open(data);
        },

        /** Close a modal/drawer by element ID. */
        close: function (id) {
            var ctrl = modalRegistry.get(id) || drawerRegistry.get(id);
            if (ctrl) return ctrl.close();
            // Fallback: remove active class directly
            var el = document.getElementById(id);
            if (el) { el.classList.remove('active', 'open', 'show'); return true; }
            return false;
        },

        /** Close every open modal and drawer. */
        closeAll: function () {
            modalRegistry.forEach(function (m)  { m.close(); });
            drawerRegistry.forEach(function (d) { d.close(); });
        },

        /** Check if a specific modal/drawer is open. */
        isOpen: function (id) {
            var ctrl = modalRegistry.get(id) || drawerRegistry.get(id);
            return ctrl ? ctrl.isOpen() : false;
        },

        /** Retrieve a registered controller. */
        get: function (id) {
            return modalRegistry.get(id) || drawerRegistry.get(id) || null;
        },

        /** Raw registries (for debugging). */
        _modals:  modalRegistry,
        _drawers: drawerRegistry
    };

    // ==========================================
    // EXPOSE
    // ==========================================
    window.ModalManager = ModalManager;

    // Namespaced alias (backward compat)
    window.AdarshModal = {
        ModalController:  ModalController,
        DrawerController: DrawerController,
        getModal:         function (id) { return modalRegistry.get(id) || null; },
        getDrawer:        function (id) { return drawerRegistry.get(id) || null; },
        openModal:        ModalManager.open,
        closeModal:       ModalManager.close,
        closeAllModals:   function () { modalRegistry.forEach(function (m) { m.close(); }); },
        closeAllDrawers:  function () { drawerRegistry.forEach(function (d) { d.close(); }); },
        registry: { modals: modalRegistry, drawers: drawerRegistry }
    };

    // Legacy globals
    window.ModalController  = ModalController;
    window.DrawerController = DrawerController;

})();


/* ── js/core/utils.js ── */

/**
 * Core Utilities Module
 * Shared helpers: HTML escape, image thumbnails, empty-state,
 * string fuzzy-matching, date/time, debounce/throttle, validation.
 *
 * @module core/utils
 * @version 3.0.0
 */

(function () {
    'use strict';

    // ==========================================
    // HTML ESCAPE (XSS prevention)
    // ==========================================
    function escapeHtml(str) {
        var div = document.createElement('div');
        div.textContent = String(str == null ? '' : str);
        return div.innerHTML;
    }

    // ==========================================
    // THUMBNAIL UTILITIES
    // ==========================================
    function getThumbPath(imagePath) {
        if (!imagePath || imagePath === '' || imagePath === 'NOT_FOUND') return null;
        if (imagePath.startsWith('PENDING:')) return null;

        // Reject values that don't look like real file paths (no extension)
        if (imagePath.indexOf('.') === -1) return null;

        var parts = imagePath.replace(/\\/g, '/').split('/');
        // Change extension to .webp for thumbnail
        var last = parts[parts.length - 1];
        var dotIdx = last.lastIndexOf('.');
        if (dotIdx !== -1) last = last.substring(0, dotIdx) + '.webp';
        parts[parts.length - 1] = last;

        if (parts.length < 2) return 'thumbs/' + parts.join('/');

        return parts[0] + '/thumbs/' + parts.slice(1).join('/');
    }

    function getImageUrl(imagePath, preferThumbnail) {
        if (preferThumbnail === undefined) preferThumbnail = true;
        if (!imagePath || imagePath === '' || imagePath === 'NOT_FOUND') {
            return { src: null, isThumbnail: false, isPlaceholder: true };
        }
        if (imagePath.startsWith('PENDING:')) {
            return { src: null, isThumbnail: false, isPlaceholder: true, isPending: true, pendingRef: imagePath.substring(8) };
        }
        var thumbPath = preferThumbnail ? getThumbPath(imagePath) : null;
        return {
            src: '/media/' + imagePath,
            thumbSrc: thumbPath ? '/media/' + thumbPath : null,
            isThumbnail: false,
            isPlaceholder: false,
            originalPath: imagePath
        };
    }

    function loadImageWithFallback(imgEl, imagePath, options) {
        options = options || {};
        var useThumbnail = options.useThumbnail !== false;
        var onLoad  = options.onLoad  || null;
        var onError = options.onError || null;
        var info = getImageUrl(imagePath, useThumbnail);

        if (info.isPlaceholder) { if (onError) onError(info); return; }

        if (useThumbnail && info.thumbSrc) {
            imgEl.onerror = function () {
                imgEl.onerror = function () { if (onError) onError(info); };
                imgEl.src = info.src;
            };
            imgEl.onload = function () { if (onLoad) onLoad(info, true); };
            imgEl.src = info.thumbSrc;
        } else {
            imgEl.onerror = function () { if (onError) onError(info); };
            imgEl.onload  = function () { if (onLoad) onLoad(info, false); };
            imgEl.src = info.src;
        }
    }

    function getShortPath(imagePath) {
        if (!imagePath) return '';
        if (imagePath.startsWith('PENDING:')) return 'Pending: ' + imagePath.substring(8);
        var parts = imagePath.split('/');
        return parts.length >= 2 ? '../' + parts.slice(-2).join('/') : imagePath;
    }

    // ==========================================
    // EMPTY STATE
    // ==========================================
    var EMPTY_STATE_CONFIG = {
        staff:          { icon: 'fa-user-slash',        title: 'No Staff Found',          message: 'Try adjusting your search or filter criteria', actionText: 'Add Staff' },
        clients:        { icon: 'fa-building-slash',    title: 'No Clients Found',        message: 'Try adjusting your search or filter criteria', actionText: 'Add Client' },
        activeClients:  { icon: 'fa-users-slash',       title: 'No Active Clients Found', message: 'No clients are currently active' },
        idCards:        { icon: 'fa-id-card-clip',      title: 'No ID Cards Found',       message: 'Upload ID cards using the bulk upload feature', actionText: 'Upload Cards' },
        groups:         { icon: 'fa-folder-open',       title: 'No Groups Found',         message: 'Create a group to start managing ID cards', actionText: 'Add Group' },
        tables:         { icon: 'fa-table',             title: 'No Tables Found',         message: 'Create a table to define ID card structure', actionText: 'Create Table' },
        searchResults:  { icon: 'fa-magnifying-glass',  title: 'No Results Found',        message: 'Try adjusting your search criteria' }
    };

    function showEmptyState(containerId, contextType, options) {
        contextType = contextType || 'searchResults';
        options = options || {};
        var container = document.getElementById(containerId);
        if (!container) return;
        var cfg = EMPTY_STATE_CONFIG[contextType] || EMPTY_STATE_CONFIG.searchResults;

        var icon = container.querySelector('i');
        if (icon) icon.className = 'fa-solid ' + (options.icon || cfg.icon);

        var title = container.querySelector('h3');
        if (title) title.textContent = options.title || cfg.title;

        var msg = container.querySelector('p');
        if (msg) msg.textContent = options.message || cfg.message;

        var actionBtn = container.querySelector('.empty-state-action');
        if (actionBtn) {
            if (options.showAction && cfg.actionText) {
                actionBtn.style.display = '';
                var btnText = actionBtn.querySelector('span') || actionBtn;
                if (btnText.tagName !== 'I') btnText.textContent = options.actionText || cfg.actionText;
            } else {
                actionBtn.style.display = 'none';
            }
        }
        container.style.display = '';
    }

    function hideEmptyState(containerId) {
        var el = document.getElementById(containerId);
        if (el) el.style.display = 'none';
    }

    // ==========================================
    // STRING UTILITIES
    // ==========================================
    function normalizeFieldName(name) {
        if (!name) return '';
        return name.toLowerCase().replace(/[\s_\-\.]/g, '').replace(/[^a-z0-9]/g, '');
    }

    function levenshteinDistance(a, b) {
        var m = a.length, n = b.length;
        var dp = Array(m + 1).fill(null).map(function () { return Array(n + 1).fill(0); });
        for (var i = 0; i <= m; i++) dp[i][0] = i;
        for (var j = 0; j <= n; j++) dp[0][j] = j;
        for (i = 1; i <= m; i++) {
            for (j = 1; j <= n; j++) {
                dp[i][j] = (a[i - 1] === b[j - 1])
                    ? dp[i - 1][j - 1]
                    : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
            }
        }
        return dp[m][n];
    }

    function findBestMatch(header, tableFields) {
        var norm = normalizeFieldName(header);
        for (var k = 0; k < tableFields.length; k++) {
            if (normalizeFieldName(tableFields[k]) === norm) return { field: tableFields[k], type: 'exact' };
        }
        var best = null, bestDist = Infinity;
        for (k = 0; k < tableFields.length; k++) {
            var nf = normalizeFieldName(tableFields[k]);
            var d  = levenshteinDistance(norm, nf);
            var max = nf.length < 5 ? 1 : 2;
            if (d <= max && d < bestDist) { bestDist = d; best = tableFields[k]; }
        }
        return best ? { field: best, type: 'fuzzy' } : null;
    }

    function normalizeImageIdentifier(identifier) {
        if (identifier == null) return '';
        var result = String(identifier).trim();
        if (!result) return '';
        var num = parseFloat(result);
        if (!isNaN(num) && num === Math.floor(num)) result = String(Math.floor(num));
        var exts = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'];
        var lower = result.toLowerCase();
        for (var i = 0; i < exts.length; i++) {
            if (lower.endsWith(exts[i])) { result = result.slice(0, -exts[i].length); break; }
        }
        return result.split(/\s+/).join(' ').toUpperCase();
    }

    // ==========================================
    // DATE / TIME
    // ==========================================
    function formatDate(date, options) {
        var d = typeof date === 'string' ? new Date(date) : date;
        var def = { weekday: 'long', year: 'numeric', month: 'short', day: '2-digit' };
        return d.toLocaleDateString('en-US', Object.assign(def, options || {}));
    }

    function formatTime(date) {
        var d = typeof date === 'string' ? new Date(date) : date;
        return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
    }

    function generateTimestamp() {
        var n = new Date();
        return '' + n.getFullYear() +
            String(n.getMonth() + 1).padStart(2, '0') +
            String(n.getDate()).padStart(2, '0') + '_' +
            String(n.getHours()).padStart(2, '0') +
            String(n.getMinutes()).padStart(2, '0') +
            String(n.getSeconds()).padStart(2, '0');
    }

    // ==========================================
    // DEBOUNCE / THROTTLE
    // ==========================================
    function debounce(func, wait) {
        wait = wait || 300;
        var timeout;
        return function () {
            var args = arguments, self = this;
            clearTimeout(timeout);
            timeout = setTimeout(function () { func.apply(self, args); }, wait);
        };
    }

    function throttle(func, limit) {
        limit = limit || 300;
        var blocked = false;
        return function () {
            if (blocked) return;
            func.apply(this, arguments);
            blocked = true;
            setTimeout(function () { blocked = false; }, limit);
        };
    }

    // ==========================================
    // BUTTON LOADING STATE
    // ==========================================
    function setButtonLoading(btn, loading, originalText) {
        if (!btn) return;
        btn.disabled = loading;
        if (loading) {
            btn.dataset._origText = btn.innerHTML;
            btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Loading...';
        } else {
            btn.innerHTML = originalText || btn.dataset._origText || btn.textContent;
        }
    }

    // ==========================================
    // VALIDATION HELPERS
    // ==========================================
    var patterns = {
        email:        /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
        phone:        /^[\d\s\-+()]{7,20}$/,
        url:          /^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([\/\w .-]*)*\/?$/,
        alphanumeric: /^[a-zA-Z0-9]+$/,
        alpha:        /^[a-zA-Z]+$/,
        numeric:      /^[0-9]+$/,
        decimal:      /^[0-9]+(\.[0-9]+)?$/,
        date:         /^\d{4}-\d{2}-\d{2}$/,
        time:         /^\d{2}:\d{2}(:\d{2})?$/
    };

    function isEmpty(v) {
        if (v == null) return true;
        if (typeof v === 'string') return v.trim() === '';
        if (Array.isArray(v)) return v.length === 0;
        if (typeof v === 'object') return Object.keys(v).length === 0;
        return false;
    }

    function isValidEmail(e)   { return !isEmpty(e) && patterns.email.test(e.trim()); }
    function isValidPhone(p)   { return !isEmpty(p) && patterns.phone.test(p.trim()); }
    function isValidUrl(u)     { return !isEmpty(u) && patterns.url.test(u.trim());   }

    function isValidLength(s, min, max) {
        if (typeof s !== 'string') return false;
        var len = s.trim().length;
        return len >= min && len <= (max || Infinity);
    }

    function matchesPattern(value, pat) {
        if (isEmpty(value)) return false;
        var re = typeof pat === 'string' ? patterns[pat] : pat;
        return re ? re.test(value) : false;
    }

    function isValidExtension(filename, allowed) {
        if (isEmpty(filename)) return false;
        var ext = filename.toLowerCase().slice(filename.lastIndexOf('.'));
        return allowed.map(function (e) { return e.toLowerCase(); }).includes(ext);
    }

    function isValidFileSize(bytes, maxMB) { return bytes <= maxMB * 1024 * 1024; }

    function validateForm(form, rules) {
        var el = typeof form === 'string' ? document.getElementById(form) : form;
        if (!el) return { valid: false, errors: { form: ['Form not found'] } };
        var errors = {}, valid = true;
        Object.keys(rules).forEach(function (fn) {
            var field = el.querySelector('[name="' + fn + '"]') || el.querySelector('#' + fn);
            if (!field) return;
            var v = field.value, fe = [], r = rules[fn];
            if (r.required && isEmpty(v))          fe.push(r.requiredMessage  || fn + ' is required');
            if (!isEmpty(v)) {
                if (r.email     && !isValidEmail(v))  fe.push(r.emailMessage     || 'Invalid email format');
                if (r.phone     && !isValidPhone(v))  fe.push(r.phoneMessage     || 'Invalid phone number');
                if (r.minLength && v.length < r.minLength) fe.push(r.minLengthMessage || 'Minimum ' + r.minLength + ' characters required');
                if (r.maxLength && v.length > r.maxLength) fe.push(r.maxLengthMessage || 'Maximum ' + r.maxLength + ' characters allowed');
                if (r.pattern   && !matchesPattern(v, r.pattern)) fe.push(r.patternMessage || 'Invalid format');
                if (r.custom    && typeof r.custom === 'function') {
                    var cr = r.custom(v, el);
                    if (cr !== true) fe.push(cr || 'Validation failed');
                }
            }
            if (fe.length) { errors[fn] = fe; valid = false; }
        });
        return { valid: valid, errors: errors };
    }

    function displayErrors(form, errors) {
        var el = typeof form === 'string' ? document.getElementById(form) : form;
        if (!el) return;
        clearErrors(el);
        Object.keys(errors).forEach(function (fn) {
            var field = el.querySelector('[name="' + fn + '"]') || el.querySelector('#' + fn);
            if (!field) return;
            field.classList.add('is-invalid', 'error');
            var c = field.parentElement.querySelector('.error-message, .invalid-feedback');
            if (!c) { c = document.createElement('div'); c.className = 'error-message invalid-feedback'; field.parentElement.appendChild(c); }
            c.textContent = errors[fn][0];
            c.style.display = 'block';
        });
    }

    function clearErrors(form) {
        var el = typeof form === 'string' ? document.getElementById(form) : form;
        if (!el) return;
        el.querySelectorAll('.is-invalid, .error').forEach(function (f) { f.classList.remove('is-invalid', 'error'); });
        el.querySelectorAll('.error-message, .invalid-feedback').forEach(function (m) { m.style.display = 'none'; m.textContent = ''; });
    }

    // ==========================================
    // EXPOSE
    // ==========================================
    window.AdarshUtils = {
        // Image
        getThumbPath: getThumbPath, getImageUrl: getImageUrl,
        loadImageWithFallback: loadImageWithFallback, getShortPath: getShortPath,
        // Empty state
        EMPTY_STATE_CONFIG: EMPTY_STATE_CONFIG,
        showEmptyState: showEmptyState, hideEmptyState: hideEmptyState,
        // Strings
        normalizeFieldName: normalizeFieldName, levenshteinDistance: levenshteinDistance,
        findBestMatch: findBestMatch, normalizeImageIdentifier: normalizeImageIdentifier,
        // Date/time
        formatDate: formatDate, formatTime: formatTime, generateTimestamp: generateTimestamp,
        // Functional
        debounce: debounce, throttle: throttle,
        // Buttons
        setButtonLoading: setButtonLoading,
        // Validation
        isEmpty: isEmpty, isValidEmail: isValidEmail, isValidPhone: isValidPhone,
        isValidUrl: isValidUrl, isValidLength: isValidLength, matchesPattern: matchesPattern,
        isValidExtension: isValidExtension, isValidFileSize: isValidFileSize,
        validateForm: validateForm, displayErrors: displayErrors, clearErrors: clearErrors,
        patterns: patterns
    };

    // Namespaced validation alias
    window.AdarshValidation = {
        isEmpty: isEmpty, isValidEmail: isValidEmail, isValidPhone: isValidPhone,
        isValidUrl: isValidUrl, isValidLength: isValidLength, matchesPattern: matchesPattern,
        isValidExtension: isValidExtension, isValidFileSize: isValidFileSize,
        validateForm: validateForm, displayErrors: displayErrors, clearErrors: clearErrors,
        patterns: patterns
    };

    // Legacy globals
    window.escapeHtml              = escapeHtml;
    window.getThumbPath            = getThumbPath;
    window.getImageUrl             = getImageUrl;
    window.loadImageWithFallback   = loadImageWithFallback;
    window.getShortPath            = getShortPath;
    window.EMPTY_STATE_CONFIG      = EMPTY_STATE_CONFIG;
    window.showEmptyState          = showEmptyState;
    window.hideEmptyState          = hideEmptyState;
    window.normalizeFieldName      = normalizeFieldName;
    window.levenshteinDistance      = levenshteinDistance;
    window.findBestMatch           = findBestMatch;
    window.normalizeImageIdentifier = normalizeImageIdentifier;
    window.debounce                = debounce;
    window.throttle                = throttle;
    window.setButtonLoading        = setButtonLoading;
    window.validateForm            = validateForm;

})();


/* ── js/core/sanitizer.js ── */

/**
 * Data Sanitizer Module
 * =====================
 * Enforces clean text-field rules across all forms and Excel imports.
 *
 * ALLOWED characters in plain text fields:
 *   Letters (a–z, A–Z, Unicode/Devanagari etc.)
 *   Digits  (0–9)
 *   Spaces
 *   Comma   ,
 *   Period  .
 *   Plus    +
 *   Apostrophe ' (common in Indian surnames: D'Souza, O'Brien)
 *   Slash   /  (common in Indian addresses: Plot 1/2)
 *
 * ALWAYS REMOVED (from ALL fields, including email):
 *   Newline \n, carriage return \r, tab \t
 *   Double quote "
 *
 * NOT ALLOWED in plain text fields (but kept for email/url fields):
 *   @, _, #, $, %, ^, &, *, (, ), [, ], {, }, |, \, :, ;, <, >, ?, ~, `
 * ALLOWED (hyphen and slash are permitted):
 *   - (hyphen), / (slash)
 *
 * @module core/sanitizer
 * @version 1.0.0
 */
(function () {
    'use strict';

    /**
     * Sanitize a plain text field value.
     * @param {string} value               Raw input text
     * @param {boolean} [keepSlash=true]   Whether to keep '/' (addresses)
     * @returns {{ value: string, changed: boolean, removed: string[] }}
     */
    function sanitizeText(value, keepSlash) {
        if (value === null || value === undefined) return { value: '', changed: false, removed: [] };
        keepSlash = keepSlash !== false; // default true

        var original = String(value);
        var result = original;
        var removed = [];

        // Step 1: Remove control chars (newlines, carriage returns, tabs)
        if (/[\n\r\t]/.test(result)) {
            result = result.replace(/[\n\r\t]+/g, ' ').trim();
            removed.push('newlines/tabs');
        }

        // Step 2: Collapse multiple spaces to one
        result = result.replace(/  +/g, ' ').trim();

        // Step 3: Remove double quotes
        if (result.indexOf('"') !== -1) {
            result = result.replace(/"/g, '');
            removed.push('double quotes (")');
        }

        // Step 4: Remove disallowed special characters
        // Allowed special: , . + ' and optionally /
        var slashPart = keepSlash ? '\\/' : '';
        var forbiddenRe = new RegExp('[^\\w\\s,\\.\\+\'' + slashPart + ']', 'g');
        // But \w includes _ which we don't want — replace \w with explicit chars
        // Allow: letters (a-z, A-Z, Unicode via \p if supported), digits 0-9, space
        // Use a permissive "remove known bad" approach for broad Unicode support
        var badCharsRe = /[_@#$%^&*()\[\]{}<>\|\\:;"~`!?=]/g;
        var stripped = result.replace(badCharsRe, '');
        if (stripped !== result) {
            removed.push('special characters (_ - @ # etc.)');
            result = stripped;
        }

        // Step 5: Collapse spaces again after removals
        result = result.replace(/  +/g, ' ').trim();

        return {
            value: result,
            changed: result !== original.replace(/[\n\r\t]+/g, ' ').trim().replace(/  +/g, ' ').trim() ? true : result !== original,
            removed: removed
        };
    }

    /**
     * Sanitize an email field — only remove newlines and double quotes.
     * @param {string} value
     * @returns {{ value: string, changed: boolean, removed: string[] }}
     */
    function sanitizeEmail(value) {
        if (!value) return { value: '', changed: false, removed: [] };
        var original = String(value);
        var result = original.replace(/[\n\r\t\s]+/g, '').replace(/"/g, '');
        return {
            value: result,
            changed: result !== original,
            removed: result !== original ? ['whitespace/newlines in email'] : []
        };
    }

    /**
     * Build a human-readable warning message from sanitizeText results.
     * @param {string[]} removedList
     * @returns {string}
     */
    function buildWarning(removedList) {
        if (!removedList || !removedList.length) return '';
        return 'Removed: ' + removedList.join(', ');
    }

    /**
     * Apply sanitizer to a single <input> or <textarea> element and show
     * an inline warning beneath it if content was changed.
     *
     * @param {HTMLElement} inputEl    The input/textarea element
     * @param {boolean}     isEmail    True for email fields → use sanitizeEmail
     */
    function sanitizeInputElement(inputEl, isEmail) {
        if (!inputEl) return;
        var raw = inputEl.value;
        var result = isEmail ? sanitizeEmail(raw) : sanitizeText(raw);
        if (result.changed) {
            inputEl.value = result.value;
            showInlineHint(inputEl, buildWarning(result.removed), 'warning');
        }
    }

    /**
     * Show (or clear) an inline hint/error message below an input element.
     * Creates a <p class="field-hint"> element on first call, reuses it after.
     *
     * @param {HTMLElement} inputEl
     * @param {string}      message   '' or null to hide
     * @param {string}      type      'warning' | 'error' | 'info'
     */
    function showInlineHint(inputEl, message, type) {
        if (!inputEl) return;
        type = type || 'warning';
        var hintId = 'hint-' + (inputEl.id || inputEl.name || Math.random().toString(36).slice(2));
        var hint = inputEl.parentElement && inputEl.parentElement.querySelector('.field-hint[data-for="' + hintId + '"]');
        if (!hint) {
            hint = document.createElement('p');
            hint.className = 'field-hint';
            hint.setAttribute('data-for', hintId);
            hint.style.cssText = 'font-size:11px;margin:2px 0 0;padding:2px 4px;border-radius:3px;';
            if (inputEl.parentElement) inputEl.parentElement.appendChild(hint);
        }
        if (!message) {
            hint.style.display = 'none';
            hint.textContent = '';
            return;
        }
        var colors = {
            warning: { bg: '#fffbeb', border: '#fde68a', color: '#92400e' },
            error:   { bg: '#fef2f2', border: '#fecaca', color: '#b91c1c' },
            info:    { bg: '#eff6ff', border: '#bfdbfe', color: '#1e40af' },
        };
        var c = colors[type] || colors.warning;
        hint.style.background = c.bg;
        hint.style.border = '1px solid ' + c.border;
        hint.style.color = c.color;
        hint.style.display = 'block';
        hint.innerHTML = '<i class="fa-solid fa-triangle-exclamation" style="margin-right:3px;"></i>' + message;
    }

    /**
     * Attach live sanitization to all text-like inputs in a form.
     * Call once after the form/drawer is opened.
     *
     * @param {HTMLElement} formEl
     */
    function attachToForm(formEl) {
        if (!formEl) return;
        var inputs = formEl.querySelectorAll('input[type="text"], input[type="tel"], textarea, input:not([type])');
        inputs.forEach(function (el) {
            var isEmail = el.type === 'email' || (el.name && el.name.toLowerCase().includes('email'));
            // Sanitize on blur (after user finishes typing)
            el.addEventListener('blur', function () {
                sanitizeInputElement(el, isEmail);
            });
            // Clear hint when user starts editing again
            el.addEventListener('input', function () {
                showInlineHint(el, '');
            });
        });
        // Also handle email inputs
        var emailInputs = formEl.querySelectorAll('input[type="email"], input[name*="email"], input[id*="email"]');
        emailInputs.forEach(function (el) {
            el.addEventListener('blur', function () { sanitizeInputElement(el, true); });
            el.addEventListener('input', function () { showInlineHint(el, ''); });
        });
    }

    /**
     * Sanitize a plain JS object of form data before API submission.
     * Fields matching email patterns use sanitizeEmail; others use sanitizeText.
     *
     * @param {Object} data         Key-value form data
     * @param {string[]} emailKeys  Field names that are email addresses
     * @returns {{ data: Object, warnings: string[] }}
     */
    function sanitizeFormData(data, emailKeys) {
        emailKeys = emailKeys || ['email'];
        var warnings = [];
        var clean = {};
        Object.keys(data).forEach(function (key) {
            var val = data[key];
            if (typeof val !== 'string') { clean[key] = val; return; }
            var isEmail = emailKeys.some(function (k) { return key.toLowerCase().includes(k); });
            var result = isEmail ? sanitizeEmail(val) : sanitizeText(val);
            clean[key] = result.value;
            if (result.changed && result.removed.length) {
                warnings.push(key + ': ' + buildWarning(result.removed));
            }
        });
        return { data: clean, warnings: warnings };
    }

    /**
     * Sanitize an array of row objects from Excel import.
     * Returns sanitized rows and list of warnings per row.
     *
     * @param {Array<Object>} rows
     * @param {string[]}      emailKeys
     * @returns {{ rows: Array<Object>, warnings: Array<{row: number, field: string, msg: string}> }}
     */
    function sanitizeExcelRows(rows, emailKeys) {
        emailKeys = emailKeys || ['email'];
        var warnings = [];
        var cleaned = rows.map(function (row, idx) {
            var result = sanitizeFormData(row, emailKeys);
            result.warnings.forEach(function (w) {
                warnings.push({ row: idx + 1, field: w.split(':')[0], msg: w });
            });
            return result.data;
        });
        return { rows: cleaned, warnings: warnings };
    }

    // ── Expose globally ──────────────────────────────────────────────
    window.DataSanitizer = {
        sanitizeText:        sanitizeText,
        sanitizeEmail:       sanitizeEmail,
        buildWarning:        buildWarning,
        sanitizeInputElement: sanitizeInputElement,
        showInlineHint:      showInlineHint,
        attachToForm:        attachToForm,
        sanitizeFormData:    sanitizeFormData,
        sanitizeExcelRows:   sanitizeExcelRows,
    };

})();


/* ── js/core/confirmation-code.js ── */

/**
 * Confirmation Code Utility
 * Centralised 10-digit numeric code generation & verification
 * used by all confirmation modals across the application.
 *
 * Usage:
 *   const code = ConfirmationCode.generate();   // "3847291056"
 *   ConfirmationCode.verify(input, expected);    // true / false
 *
 * @module core/confirmation-code
 * @version 1.0.0
 */
(function () {
    'use strict';

    var CODE_LENGTH = 10;
    var CODE_MIN    = 1000000000;  // 10-digit minimum
    var CODE_MAX    = 9000000000;  // range so result is always 10 digits

    /**
     * Generate a random 10-digit numeric string.
     * @returns {string} e.g. "4829103756"
     */
    function generate() {
        return String(Math.floor(CODE_MIN + Math.random() * CODE_MAX));
    }

    /**
     * Verify that the user-entered value matches the expected code.
     * Trims whitespace and coerces both to strings before comparing.
     * @param {string} input    - value entered by user
     * @param {string} expected - the code that was displayed
     * @returns {boolean}
     */
    function verify(input, expected) {
        if (!input || !expected) return false;
        return String(input).trim() === String(expected).trim();
    }

    /**
     * Check whether a string looks like a valid 10-digit numeric code.
     * @param {string} value
     * @returns {boolean}
     */
    function isValid(value) {
        if (!value) return false;
        var v = String(value).trim();
        return v.length === CODE_LENGTH && /^\d{10}$/.test(v);
    }

    // Public API
    var ConfirmationCode = {
        generate: generate,
        verify:   verify,
        isValid:  isValid,
        CODE_LENGTH: CODE_LENGTH
    };

    // Expose globally
    window.ConfirmationCode = ConfirmationCode;

})();


/* ── js/core/download-manager.js ── */

/**
 * Download Manager Module
 * Manages concurrent downloads with progress tracking, cancel support,
 * priority queuing, and bandwidth throttling.
 *
 * Features:
 *  - Max 3 simultaneous downloads
 *  - Real progress bars with percentage & ETA
 *  - Cancel button on each download toast
 *  - Toast persists until cancelled or completed
 *  - If combined active downloads > 500 MB, new downloads wait in queue
 *  - If adding a 4th download, oldest active download is cancelled
 *
 * Public API:
 *   DownloadManager.start(options)   → downloadId
 *   DownloadManager.cancel(id)
 *   DownloadManager.cancelAll()
 *   DownloadManager.getActive()      → [{id, name, progress, ...}]
 *
 * @module core/download-manager
 * @version 1.0.0
 */
(function () {
    'use strict';

    // =========================================
    // CONSTANTS
    // =========================================
    var MAX_CONCURRENT = 3;
    var SIZE_THRESHOLD = 500 * 1024 * 1024; // 500 MB
    var COMPLETE_TOAST_DURATION = 5000;      // 5s auto-hide after complete
    var TOAST_CONTAINER_ID = 'downloadToastContainer';

    // =========================================
    // STATE
    // =========================================
    var _nextId = 1;
    var _active = {};    // id → { id, name, xhr, startTime, loaded, total, toastEl, status }
    var _queue = [];     // [{ id, options }]  waiting to start
    var _currentOverlayId = null;   // ID of the download currently shown in blocking overlay
    var _overlayStartTime = null;   // Track start time for ETA calculation

    // =========================================
    // BLOCKING OVERLAY HELPERS (Enhanced)
    // =========================================
    function _showBlockingOverlay(id, name, itemCount) {
        var overlay = document.getElementById('blockingOverlay');
        if (!overlay) return;
        _currentOverlayId = id;
        _overlayStartTime = Date.now();

        var content = overlay.querySelector('#blockingOverlayContent');
        var iconEl = overlay.querySelector('#blockingOverlayIconInner');
        var titleEl = overlay.querySelector('#blockingOverlayTitle');
        var msgEl = overlay.querySelector('#blockingOverlayMessage');
        var barEl = overlay.querySelector('#blockingOverlayBar');
        var pctEl = overlay.querySelector('#blockingOverlayPercent');
        var timeEl = overlay.querySelector('#blockingOverlayTime');
        var sizeEl = overlay.querySelector('#blockingOverlaySize');
        var badgeEl = overlay.querySelector('#blockingOverlayBadge');
        var badgeCount = overlay.querySelector('#blockingOverlayBadgeCount');
        var cancelBtn = overlay.querySelector('#blockingOverlayCancelBtn');
        var doneBtn = overlay.querySelector('#blockingOverlayDoneBtn');

        // Set preparing state
        if (content) content.className = 'blocking-overlay-content preparing';
        if (iconEl) iconEl.className = 'fa-solid fa-gear fa-spin';
        if (titleEl) titleEl.textContent = 'Preparing Download';
        if (msgEl) msgEl.textContent = 'Generating ' + name + '...';
        if (barEl) { barEl.style.width = '0%'; barEl.classList.add('indeterminate'); }
        if (pctEl) pctEl.textContent = '';
        if (timeEl) timeEl.textContent = itemCount ? '~' + Math.ceil(itemCount * 0.5) + 's' : '';
        if (sizeEl) sizeEl.textContent = '';

        // Show badge if item count provided
        if (badgeEl && itemCount && itemCount > 0) {
            badgeEl.style.display = 'inline-flex';
            if (badgeCount) badgeCount.textContent = itemCount + ' item' + (itemCount > 1 ? 's' : '');
        } else if (badgeEl) {
            badgeEl.style.display = 'none';
        }

        // Wire cancel button
        if (cancelBtn) {
            cancelBtn.style.display = 'inline-flex';
            cancelBtn.querySelector('span').textContent = 'Cancel';
            cancelBtn.onclick = function() { _cancel(id); };
        }
        if (doneBtn) doneBtn.style.display = 'none';

        overlay.style.display = 'flex';
    }

    function _updateBlockingOverlay(id, pct, message, sizeInfo) {
        if (_currentOverlayId !== id) return;
        var overlay = document.getElementById('blockingOverlay');
        if (!overlay) return;

        var content = overlay.querySelector('#blockingOverlayContent');
        var iconEl = overlay.querySelector('#blockingOverlayIconInner');
        var titleEl = overlay.querySelector('#blockingOverlayTitle');
        var msgEl = overlay.querySelector('#blockingOverlayMessage');
        var barEl = overlay.querySelector('#blockingOverlayBar');
        var pctEl = overlay.querySelector('#blockingOverlayPercent');
        var timeEl = overlay.querySelector('#blockingOverlayTime');
        var sizeElm = overlay.querySelector('#blockingOverlaySize');

        // Switch to downloading state
        if (content && !content.classList.contains('downloading')) {
            content.className = 'blocking-overlay-content downloading';
            if (iconEl) iconEl.className = 'fa-solid fa-download';
            if (titleEl) titleEl.textContent = 'Downloading...';
        }

        if (msgEl && message) msgEl.textContent = message;
        if (barEl) {
            barEl.classList.remove('indeterminate');
            barEl.style.width = Math.min(pct, 100) + '%';
        }
        if (pctEl) pctEl.textContent = Math.round(pct) + '%';

        // Calculate ETA based on progress
        if (timeEl && _overlayStartTime && pct > 5) {
            var elapsed = (Date.now() - _overlayStartTime) / 1000;
            var totalEst = elapsed / (pct / 100);
            var remaining = Math.ceil(totalEst - elapsed);
            if (remaining > 0 && remaining < 3600) {
                timeEl.textContent = remaining < 60 ? '~' + remaining + 's' : '~' + Math.ceil(remaining / 60) + 'm';
            } else {
                timeEl.textContent = '';
            }
        }

        if (sizeElm && sizeInfo) sizeElm.textContent = sizeInfo;
    }

    function _completeBlockingOverlay(id, success, message) {
        if (_currentOverlayId !== id) return;
        var overlay = document.getElementById('blockingOverlay');
        if (!overlay) return;

        var content = overlay.querySelector('#blockingOverlayContent');
        var iconEl = overlay.querySelector('#blockingOverlayIconInner');
        var titleEl = overlay.querySelector('#blockingOverlayTitle');
        var msgEl = overlay.querySelector('#blockingOverlayMessage');
        var barEl = overlay.querySelector('#blockingOverlayBar');
        var pctEl = overlay.querySelector('#blockingOverlayPercent');
        var timeEl = overlay.querySelector('#blockingOverlayTime');
        var cancelBtn = overlay.querySelector('#blockingOverlayCancelBtn');
        var doneBtn = overlay.querySelector('#blockingOverlayDoneBtn');

        if (success) {
            if (content) content.className = 'blocking-overlay-content complete';
            if (iconEl) iconEl.className = 'fa-solid fa-check';
            if (titleEl) titleEl.textContent = 'Download Complete!';
            if (msgEl) msgEl.textContent = message || 'File saved to your device';
            if (barEl) barEl.style.width = '100%';
            if (pctEl) pctEl.textContent = '100%';
            if (timeEl) timeEl.textContent = '';
            if (cancelBtn) cancelBtn.style.display = 'none';
            if (doneBtn) {
                doneBtn.style.display = 'inline-flex';
                doneBtn.onclick = function() { _hideBlockingOverlay(id); };
            }
            // Auto-close after 3s
            setTimeout(function() { _hideBlockingOverlay(id); }, 3000);
        } else {
            if (content) content.className = 'blocking-overlay-content error';
            if (iconEl) iconEl.className = 'fa-solid fa-xmark';
            if (titleEl) titleEl.textContent = 'Download Failed';
            if (msgEl) msgEl.textContent = message || 'Something went wrong';
            if (barEl) barEl.style.width = '0%';
            if (pctEl) pctEl.textContent = '';
            if (timeEl) timeEl.textContent = '';
            if (cancelBtn) {
                cancelBtn.style.display = 'inline-flex';
                cancelBtn.querySelector('span').textContent = 'Close';
                cancelBtn.onclick = function() { _hideBlockingOverlay(id); };
            }
            if (doneBtn) doneBtn.style.display = 'none';
        }
    }

    function _hideBlockingOverlay(id) {
        if (_currentOverlayId !== id) return;
        var overlay = document.getElementById('blockingOverlay');
        if (overlay) overlay.style.display = 'none';
        _currentOverlayId = null;
        _overlayStartTime = null;
    }

    // =========================================
    // TOAST CONTAINER (stacks download toasts)
    // =========================================
    function _ensureContainer() {
        var c = document.getElementById(TOAST_CONTAINER_ID);
        if (c) return c;
        c = document.createElement('div');
        c.id = TOAST_CONTAINER_ID;
        c.style.cssText = 'position:fixed;bottom:12px;right:12px;z-index:99999;' +
            'display:flex;flex-direction:column-reverse;gap:8px;max-width:380px;width:100%;pointer-events:none;';
        document.body.appendChild(c);
        return c;
    }

    // =========================================
    // CREATE A DOWNLOAD TOAST ELEMENT
    // =========================================
    function _createToast(id, name) {
        var el = document.createElement('div');
        el.id = 'dl-toast-' + id;
        el.className = 'dl-toast dl-toast-active';
        el.style.cssText = 'pointer-events:auto;background:linear-gradient(135deg,#6366f1 0%,#4f46e5 100%);' +
            'color:#fff;border-radius:8px;padding:10px 12px;min-width:280px;max-width:380px;' +
            'box-shadow:0 4px 20px rgba(0,0,0,.25);font-size:13px;opacity:0;transform:translateY(10px);' +
            'transition:opacity .25s,transform .25s;';

        // Build toast DOM safely (no innerHTML with dynamic data)
        var topRow = document.createElement('div');
        topRow.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:6px;';

        var spinner = document.createElement('i');
        spinner.className = 'fa-solid fa-spinner fa-spin';
        spinner.style.cssText = 'font-size:16px;flex-shrink:0;';
        topRow.appendChild(spinner);

        var nameSpan = document.createElement('span');
        nameSpan.className = 'dl-toast-name';
        nameSpan.style.cssText = 'flex:1;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
        nameSpan.textContent = name;
        topRow.appendChild(nameSpan);

        var pctSpan = document.createElement('span');
        pctSpan.className = 'dl-toast-pct';
        pctSpan.style.cssText = 'min-width:40px;text-align:right;font-weight:700;font-size:14px;';
        pctSpan.textContent = '0%';
        topRow.appendChild(pctSpan);

        var cancelBtn = document.createElement('button');
        cancelBtn.className = 'dl-toast-cancel';
        cancelBtn.title = 'Cancel';
        cancelBtn.style.cssText = 'background:rgba(255,255,255,.2);border:none;color:#fff;width:24px;height:24px;' +
            'border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;' +
            'flex-shrink:0;font-size:12px;transition:background .15s;';
        var cancelIcon = document.createElement('i');
        cancelIcon.className = 'fa-solid fa-xmark';
        cancelBtn.appendChild(cancelIcon);
        cancelBtn.addEventListener('mouseenter', function () { this.style.background = 'rgba(255,255,255,.35)'; });
        cancelBtn.addEventListener('mouseleave', function () { this.style.background = 'rgba(255,255,255,.2)'; });
        topRow.appendChild(cancelBtn);

        el.appendChild(topRow);

        var bottomRow = document.createElement('div');
        bottomRow.style.cssText = 'display:flex;align-items:center;gap:8px;';

        var barBg = document.createElement('div');
        barBg.className = 'dl-toast-bar-bg';
        barBg.style.cssText = 'flex:1;background:rgba(255,255,255,.25);border-radius:3px;height:6px;overflow:hidden;';

        var bar = document.createElement('div');
        bar.className = 'dl-toast-bar';
        bar.style.cssText = 'height:100%;width:0%;background:linear-gradient(90deg,#fff,#fffc);' +
            'border-radius:3px;transition:width .2s;box-shadow:0 0 6px rgba(255,255,255,.4);';
        barBg.appendChild(bar);
        bottomRow.appendChild(barBg);

        var eta = document.createElement('span');
        eta.className = 'dl-toast-eta';
        eta.style.cssText = 'font-size:11px;opacity:.7;min-width:48px;text-align:right;';
        eta.textContent = '--';
        bottomRow.appendChild(eta);

        el.appendChild(bottomRow);

        // Wire cancel button
        cancelBtn.addEventListener('click', function (e) {
            e.stopPropagation();
            _cancel(id);
        });

        var container = _ensureContainer();
        container.appendChild(el);

        // Trigger enter animation
        requestAnimationFrame(function () {
            el.style.opacity = '1';
            el.style.transform = 'translateY(0)';
        });

        return el;
    }

    // =========================================
    // UPDATE TOAST PROGRESS
    // =========================================
    function _updateToast(dl, loaded, total) {
        dl.loaded = loaded;
        dl.total = total;

        var el = dl.toastEl;
        if (!el) return;

        var pct = total > 0 ? Math.min(Math.round((loaded / total) * 100), 100) : 0;
        var bar = el.querySelector('.dl-toast-bar');
        var pctEl = el.querySelector('.dl-toast-pct');
        var etaEl = el.querySelector('.dl-toast-eta');

        if (bar) bar.style.width = pct + '%';
        if (pctEl) pctEl.textContent = total > 0 ? pct + '%' : '...';

        // ETA calculation
        if (etaEl && total > 0 && loaded > 0) {
            var elapsed = (Date.now() - dl.startTime) / 1000;
            var speed = loaded / elapsed; // bytes/sec
            var remaining = (total - loaded) / speed;
            etaEl.textContent = _formatEta(remaining);
        } else if (etaEl) {
            etaEl.textContent = '--';
        }
    }

    // =========================================
    // MARK TOAST AS COMPLETE / ERROR / CANCELLED
    // =========================================
    function _finishToast(dl, status, message) {
        // Complete blocking overlay with success/error state
        var overlaySuccess = status === 'complete';
        var overlayMsg = message || (overlaySuccess ? 'Downloaded successfully!' : 'Download failed');
        _completeBlockingOverlay(dl.id, overlaySuccess, overlayMsg);
        
        var el = dl.toastEl;
        if (!el) return;

        dl.status = status;

        var icon = el.querySelector('i:first-child');
        var nameEl = el.querySelector('.dl-toast-name');
        var pctEl = el.querySelector('.dl-toast-pct');
        var bar = el.querySelector('.dl-toast-bar');
        var etaEl = el.querySelector('.dl-toast-eta');
        var cancelBtn = el.querySelector('.dl-toast-cancel');

        // Update icon
        if (icon) {
            icon.className = status === 'complete'
                ? 'fa-solid fa-check-circle'
                : status === 'cancelled'
                    ? 'fa-solid fa-ban'
                    : 'fa-solid fa-times-circle';
            icon.style.animation = 'none';
        }

        // Update message
        if (nameEl) nameEl.textContent = message || dl.name;
        if (pctEl) pctEl.textContent = status === 'complete' ? '100%' : '';
        if (bar) bar.style.width = status === 'complete' ? '100%' : bar.style.width;
        if (etaEl) etaEl.textContent = '';

        // Style based on status
        if (status === 'complete') {
            el.style.background = 'linear-gradient(135deg,#10b981 0%,#059669 100%)';
        } else if (status === 'cancelled') {
            el.style.background = 'linear-gradient(135deg,#f59e0b 0%,#d97706 100%)';
        } else {
            el.style.background = 'linear-gradient(135deg,#ef4444 0%,#dc2626 100%)';
        }

        // Change cancel button to dismiss (X)
        if (cancelBtn) {
            cancelBtn.title = 'Dismiss';
            cancelBtn.onclick = function (e) {
                e.stopPropagation();
                _removeToast(dl.id);
            };
        }

        // Auto-dismiss after duration
        setTimeout(function () { _removeToast(dl.id); }, COMPLETE_TOAST_DURATION);
    }

    function _removeToast(id) {
        var dl = _active[id];
        if (!dl || !dl.toastEl) return;

        var el = dl.toastEl;
        el.style.opacity = '0';
        el.style.transform = 'translateY(10px)';
        setTimeout(function () {
            if (el.parentNode) el.parentNode.removeChild(el);
        }, 300);

        delete _active[id];
        _processQueue();
    }

    // =========================================
    // QUEUE MANAGEMENT
    // =========================================
    function _getActiveTotalBytes() {
        var sum = 0;
        for (var id in _active) {
            if (_active[id].status === 'downloading') {
                sum += _active[id].total || 0;
            }
        }
        return sum;
    }

    function _getActiveCount() {
        var count = 0;
        for (var id in _active) {
            if (_active[id].status === 'downloading') count++;
        }
        return count;
    }

    function _processQueue() {
        while (_queue.length > 0 && _getActiveCount() < MAX_CONCURRENT) {
            // Check size threshold — if active bytes > 500MB, don't start another
            if (_getActiveTotalBytes() > SIZE_THRESHOLD && _getActiveCount() > 0) {
                break;
            }
            var next = _queue.shift();
            _startXhr(next.id, next.options);
        }
    }

    // =========================================
    // CANCEL
    // =========================================
    function _cancel(id) {
        // Check active downloads
        var dl = _active[id];
        if (dl) {
            if (dl._indeterminateTimer) { clearInterval(dl._indeterminateTimer); dl._indeterminateTimer = null; }
            if (dl.xhr && dl.status === 'downloading') {
                dl.xhr.abort();
            }
            _finishToast(dl, 'cancelled', 'Download cancelled');
            return;
        }

        // Check queue
        for (var i = 0; i < _queue.length; i++) {
            if (_queue[i].id === id) {
                // Remove from queue, also remove toast
                var qEntry = _queue.splice(i, 1)[0];
                var qDl = _active[qEntry.id];
                if (qDl) _finishToast(qDl, 'cancelled', 'Download cancelled');
                return;
            }
        }
    }

    function _cancelAll() {
        // Cancel all queued
        while (_queue.length > 0) {
            var q = _queue.pop();
            var dl = _active[q.id];
            if (dl) _finishToast(dl, 'cancelled', 'Download cancelled');
        }
        // Cancel all active
        for (var id in _active) {
            if (_active[id].status === 'downloading') {
                _cancel(parseInt(id));
            }
        }
    }

    // =========================================
    // CORE XHR DOWNLOAD
    // =========================================
    function _startXhr(id, opts) {
        var dl = _active[id];
        if (!dl) return;

        dl.status = 'downloading';
        dl.startTime = Date.now();

        // Extract item count from body if available (card_ids array)
        var itemCount = 0;
        if (opts.body) {
            var bodyObj = typeof opts.body === 'string' ? JSON.parse(opts.body) : opts.body;
            if (bodyObj.card_ids && Array.isArray(bodyObj.card_ids)) {
                itemCount = bodyObj.card_ids.length;
            }
        }

        // Show blocking overlay with item count
        _showBlockingOverlay(id, dl.name, itemCount);

        var xhr = new XMLHttpRequest();
        dl.xhr = xhr;

        xhr.open(opts.method || 'POST', opts.url, true);
        xhr.responseType = 'blob';
        xhr.timeout = 600000; // 10 minutes for large exports

        // Set headers
        if (opts.headers) {
            for (var h in opts.headers) {
                xhr.setRequestHeader(h, opts.headers[h]);
            }
        }
        // Always set Content-Type for POST
        if ((opts.method || 'POST') === 'POST') {
            xhr.setRequestHeader('Content-Type', 'application/json');
        }
        // CSRF
        if (typeof getCSRFToken === 'function') {
            xhr.setRequestHeader('X-CSRFToken', getCSRFToken());
        }
        // Disable compression to ensure Content-Length is readable for progress tracking
        xhr.setRequestHeader('Accept-Encoding', 'identity');

        xhr.onprogress = function (e) {
            if (e.lengthComputable) {
                _updateToast(dl, e.loaded, e.total);
                var pct = Math.min(Math.round((e.loaded / e.total) * 100), 100);
                var sizeInfo = _formatBytes(e.loaded) + ' / ' + _formatBytes(e.total);
                _updateBlockingOverlay(dl.id, pct, 'Downloading ' + dl.name + '...', sizeInfo);
                // Clear indeterminate timer if we now have real progress
                if (dl._indeterminateTimer) {
                    clearInterval(dl._indeterminateTimer);
                    dl._indeterminateTimer = null;
                    var bar2 = dl.toastEl ? dl.toastEl.querySelector('.dl-toast-bar') : null;
                    if (bar2) { bar2.style.animation = ''; bar2.dataset.indeterminate = ''; }
                }
            } else if (!dl._indeterminateTimer) {
                // No Content-Length — use time-based estimation (exponential approach to 85%)
                var _indStart = Date.now();
                dl._indeterminateTimer = setInterval(function() {
                    var bar = dl.toastEl ? dl.toastEl.querySelector('.dl-toast-bar') : null;
                    var pctEl = dl.toastEl ? dl.toastEl.querySelector('.dl-toast-pct') : null;
                    if (!bar) return;
                    bar.style.animation = '';
                    bar.dataset.indeterminate = '';
                    var elapsed = (Date.now() - _indStart) / 1000;
                    var estPct = Math.round(85 * (1 - Math.exp(-elapsed / 15)));
                    bar.style.width = estPct + '%';
                    if (pctEl) pctEl.textContent = estPct + '%';
                    _updateBlockingOverlay(dl.id, estPct, 'Generating ' + dl.name + '...', null);
                }, 500);
            }
        };

        xhr.onload = function () {
            if (dl._indeterminateTimer) { clearInterval(dl._indeterminateTimer); dl._indeterminateTimer = null; }
            if (dl.status !== 'downloading') return; // was cancelled

            if (xhr.status === 200) {
                // Success — trigger download
                var blob = xhr.response;
                var filename = opts.filename || _extractFilename(xhr, opts.fallbackExt || 'zip');
                _triggerBlobDownload(blob, filename);
                _finishToast(dl, 'complete', opts.completeMessage || 'Downloaded ' + filename);

                // Callback
                if (typeof opts.onComplete === 'function') {
                    try { opts.onComplete(blob, filename); } catch (e) { console.error(e); }
                }
            } else {
                // Error
                var errMsg = 'Download failed (HTTP ' + xhr.status + ')';
                try {
                    var reader = new FileReader();
                    reader.onload = function () {
                        try {
                            var errData = JSON.parse(reader.result);
                            errMsg = errData.message || errMsg;
                        } catch (e) { /* use default */ }
                        _finishToast(dl, 'error', errMsg);
                        if (typeof opts.onError === 'function') opts.onError(errMsg);
                    };
                    reader.readAsText(xhr.response);
                } catch (e) {
                    _finishToast(dl, 'error', errMsg);
                    if (typeof opts.onError === 'function') opts.onError(errMsg);
                }
            }
        };

        xhr.onerror = function () {
            if (dl._indeterminateTimer) { clearInterval(dl._indeterminateTimer); dl._indeterminateTimer = null; }
            if (dl.status !== 'downloading') return;
            _finishToast(dl, 'error', 'Network error — download failed');
            if (typeof opts.onError === 'function') opts.onError('Network error');
        };

        xhr.ontimeout = function () {
            if (dl._indeterminateTimer) { clearInterval(dl._indeterminateTimer); dl._indeterminateTimer = null; }
            if (dl.status !== 'downloading') return;
            _finishToast(dl, 'error', 'Download timed out — the server took too long to respond. Please try again.');
            if (typeof opts.onError === 'function') opts.onError('Timeout');
        };

        xhr.onabort = function () {
            if (dl._indeterminateTimer) { clearInterval(dl._indeterminateTimer); dl._indeterminateTimer = null; }
            // Handled by _cancel
        };

        xhr.send(opts.body ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : null);
    }

    // =========================================
    // START A DOWNLOAD (PUBLIC)
    // =========================================
    function start(options) {
        /**
         * options:
         *   name          – display name for toast (e.g. "ID Cards DOCX")
         *   url           – endpoint URL
         *   method        – HTTP method (default: POST)
         *   body          – request body (object or string)
         *   headers       – extra headers
         *   filename      – override filename (optional)
         *   fallbackExt   – fallback extension if no Content-Disposition (default: zip)
         *   completeMessage – toast message on success
         *   onComplete    – callback(blob, filename)
         *   onError       – callback(errorMsg)
         *
         * Returns: downloadId (number)
         */
        var id = _nextId++;
        var name = options.name || 'Download #' + id;

        // Create toast immediately
        var toastEl = _createToast(id, name);

        _active[id] = {
            id: id,
            name: name,
            xhr: null,
            startTime: null,
            loaded: 0,
            total: 0,
            toastEl: toastEl,
            status: 'pending'
        };

        var activeCount = _getActiveCount();

        // If adding beyond MAX_CONCURRENT, cancel the oldest active download
        if (activeCount >= MAX_CONCURRENT) {
            var oldestId = null;
            var oldestTime = Infinity;
            for (var aid in _active) {
                var a = _active[aid];
                if (a.status === 'downloading' && a.startTime && a.startTime < oldestTime) {
                    oldestTime = a.startTime;
                    oldestId = parseInt(aid);
                }
            }
            if (oldestId !== null) {
                _cancel(oldestId);
            }
        }

        // Check if we can start immediately or need to queue
        if (_getActiveCount() < MAX_CONCURRENT) {
            // Check size threshold
            if (_getActiveTotalBytes() > SIZE_THRESHOLD && _getActiveCount() > 0) {
                // Queue it — will start when current finishes
                _queue.push({ id: id, options: options });
                _updateToastQueued(_active[id]);
            } else {
                _startXhr(id, options);
            }
        } else {
            _queue.push({ id: id, options: options });
            _updateToastQueued(_active[id]);
        }

        return id;
    }

    function _updateToastQueued(dl) {
        if (!dl || !dl.toastEl) return;
        var pctEl = dl.toastEl.querySelector('.dl-toast-pct');
        var etaEl = dl.toastEl.querySelector('.dl-toast-eta');
        if (pctEl) pctEl.textContent = '';
        if (etaEl) etaEl.textContent = 'Queued';

        var bar = dl.toastEl.querySelector('.dl-toast-bar');
        if (bar) {
            bar.style.width = '100%';
            bar.style.opacity = '0.3';
            bar.style.animation = '2s ease-in-out infinite alternate pulse-bar';
        }
    }

    // =========================================
    // SPECIAL: Image download (non-blob JSON response)
    // For image downloads that return JSON with base64 ZIPs
    // =========================================
    function startImageDownload(options) {
        /**
         * Special handler for image exports that return JSON with zip_files array.
         * options: same as start() but handles JSON response differently.
         * Returns: downloadId
         */
        var id = _nextId++;
        var name = options.name || 'Images Download';
        var toastEl = _createToast(id, name);

        _active[id] = {
            id: id,
            name: name,
            xhr: null,
            startTime: Date.now(),
            loaded: 0,
            total: 0,
            toastEl: toastEl,
            status: 'downloading'
        };

        var dl = _active[id];

        // Extract item count from body if available
        var itemCount = 0;
        if (options.body) {
            var bodyObj = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
            if (bodyObj.card_ids && Array.isArray(bodyObj.card_ids)) {
                itemCount = bodyObj.card_ids.length;
            }
        }

        // Show blocking overlay for image download with item count
        _showBlockingOverlay(id, name, itemCount);

        var xhr = new XMLHttpRequest();
        dl.xhr = xhr;

        xhr.open(options.method || 'POST', options.url, true);
        xhr.timeout = 600000; // 10 minutes for large image exports
        xhr.setRequestHeader('Content-Type', 'application/json');
        if (typeof getCSRFToken === 'function') {
            xhr.setRequestHeader('X-CSRFToken', getCSRFToken());
        }

        xhr.onprogress = function (e) {
            if (e.lengthComputable) {
                _updateToast(dl, e.loaded, e.total);
                var pct = Math.min(Math.round((e.loaded / e.total) * 100), 100);
                _updateBlockingOverlay(dl.id, pct, 'Downloading images... ' + pct + '%');
            }
        };

        xhr.onload = function () {
            if (dl.status !== 'downloading') return;

            if (xhr.status === 200) {
                try {
                    var response = JSON.parse(xhr.responseText);
                    if (response.success && response.zip_files && response.zip_files.length > 0) {
                        var totalZips = response.zip_files.length;
                        var downloadIndex = 0;

                        function downloadNextZip() {
                            if (dl.status !== 'downloading') return;
                            if (downloadIndex >= totalZips) {
                                _finishToast(dl, 'complete',
                                    'Downloaded ' + totalZips + ' ZIP(s) with ' + (response.total_images || '?') + ' images');
                                if (typeof options.onComplete === 'function') {
                                    try { options.onComplete(); } catch (e) { console.error(e); }
                                }
                                return;
                            }

                            var zipInfo = response.zip_files[downloadIndex];
                            _updateToast(dl, downloadIndex, totalZips);

                            try {
                                // CSP-safe base64 → Blob (no fetch('data:') needed)
                                var bin = atob(zipInfo.data);
                                var bytes = new Uint8Array(bin.length);
                                for (var j = 0; j < bin.length; j++) bytes[j] = bin.charCodeAt(j);
                                var blob = new Blob([bytes], { type: 'application/zip' });

                                _triggerBlobDownload(blob, zipInfo.filename);
                                downloadIndex++;
                                var pctEl = dl.toastEl ? dl.toastEl.querySelector('.dl-toast-pct') : null;
                                if (pctEl) pctEl.textContent = downloadIndex + '/' + totalZips;
                                setTimeout(downloadNextZip, 300);
                            } catch (err) {
                                console.error('ZIP download failed:', err);
                                _finishToast(dl, 'error', 'Failed to process ZIP file');
                            }
                        }

                        downloadNextZip();
                    } else {
                        _finishToast(dl, 'error', response.message || 'No images found');
                        if (typeof options.onError === 'function') options.onError(response.message);
                    }
                } catch (e) {
                    _finishToast(dl, 'error', 'Failed to process response');
                    console.error(e);
                }
            } else {
                _finishToast(dl, 'error', 'Image download failed (HTTP ' + xhr.status + ')');
            }
        };

        xhr.onerror = function () {
            if (dl.status !== 'downloading') return;
            _finishToast(dl, 'error', 'Network error — download failed');
        };

        xhr.ontimeout = function () {
            if (dl.status !== 'downloading') return;
            _finishToast(dl, 'error', 'Image download timed out — too many images or slow connection. Try fewer cards.');
        };

        xhr.send(options.body ? (typeof options.body === 'string' ? options.body : JSON.stringify(options.body)) : null);

        return id;
    }

    // =========================================
    // HELPERS
    // =========================================
    function _triggerBlobDownload(blob, filename) {
        var url = window.URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        setTimeout(function () {
            window.URL.revokeObjectURL(url);
            if (a.parentNode) a.parentNode.removeChild(a);
        }, 100);
    }

    function _extractFilename(xhr, fallbackExt) {
        var disposition = xhr.getResponseHeader('Content-Disposition');
        if (disposition) {
            var match = disposition.match(/filename\*?=(?:UTF-8''|"?)([^";]+)"?/i);
            if (match && match[1]) return decodeURIComponent(match[1]);
        }
        var clientName = (typeof CLIENT_NAME !== 'undefined' ? CLIENT_NAME : '').replace(/\s+/g, '');
        var tableName = (typeof TABLE_NAME !== 'undefined' ? TABLE_NAME : '').replace(/\s+/g, '');
        var status = (typeof CURRENT_STATUS !== 'undefined' ? CURRENT_STATUS : 'pending');
        var statusCap = status.charAt(0).toUpperCase() + status.slice(1);
        var parts = [clientName, tableName, statusCap].filter(Boolean);
        return (parts.length ? parts.join('_') : 'export') + '.' + fallbackExt;
    }

    function _formatEta(seconds) {
        if (!isFinite(seconds) || seconds < 0) return '--';
        if (seconds < 60) return Math.ceil(seconds) + 's';
        if (seconds < 3600) return Math.ceil(seconds / 60) + 'm';
        return Math.floor(seconds / 3600) + 'h ' + Math.ceil((seconds % 3600) / 60) + 'm';
    }

    function _formatBytes(bytes) {
        if (!bytes || bytes === 0) return '0 B';
        var units = ['B', 'KB', 'MB', 'GB'];
        var i = Math.floor(Math.log(bytes) / Math.log(1024));
        i = Math.min(i, units.length - 1);
        var val = bytes / Math.pow(1024, i);
        return val.toFixed(i === 0 ? 0 : 1) + ' ' + units[i];
    }

    function _escHtml(str) {
        var div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
    }

    // =========================================
    // CSS INJECTION (animations for indeterminate/queued)
    // =========================================
    (function injectStyles() {
        if (document.getElementById('dl-mgr-styles')) return;
        var style = document.createElement('style');
        style.id = 'dl-mgr-styles';
        style.textContent =
            '@keyframes indeterminate-bar{0%{transform:translateX(-100%)}100%{transform:translateX(300%)}}' +
            '@keyframes pulse-bar{0%{opacity:.2}100%{opacity:.5}}' +
            '.dl-toast{font-family:system-ui,-apple-system,sans-serif;}';
        document.head.appendChild(style);
    })();

    // =========================================
    // PUBLIC API
    // =========================================
    var DownloadManager = {
        start: start,
        startImageDownload: startImageDownload,
        cancel: _cancel,
        cancelAll: _cancelAll,
        getActive: function () {
            var list = [];
            for (var id in _active) {
                var dl = _active[id];
                list.push({
                    id: dl.id,
                    name: dl.name,
                    status: dl.status,
                    progress: dl.total > 0 ? Math.round((dl.loaded / dl.total) * 100) : 0,
                    loaded: dl.loaded,
                    total: dl.total
                });
            }
            return list;
        },
        // Public API for Upload blocking overlay (can be called from any upload code)
        showUploadOverlay: function(message, cancelFn) {
            var overlay = document.getElementById('blockingOverlay');
            if (!overlay) return;
            _currentOverlayId = 'upload-' + Date.now();
            var msgEl = overlay.querySelector('#blockingOverlayMessage');
            var barEl = overlay.querySelector('#blockingOverlayBar');
            var cancelBtn = overlay.querySelector('#blockingOverlayCancelBtn');
            if (msgEl) msgEl.textContent = message || 'Uploading...';
            if (barEl) barEl.style.width = '0%';
            if (cancelBtn) {
                cancelBtn.onclick = function() {
                    if (typeof cancelFn === 'function') cancelFn();
                    DownloadManager.hideUploadOverlay();
                };
            }
            overlay.style.display = 'flex';
            return _currentOverlayId;
        },
        updateUploadOverlay: function(pct, message) {
            var overlay = document.getElementById('blockingOverlay');
            if (!overlay) return;
            var msgEl = overlay.querySelector('#blockingOverlayMessage');
            var barEl = overlay.querySelector('#blockingOverlayBar');
            if (msgEl && message) msgEl.textContent = message;
            if (barEl) barEl.style.width = pct + '%';
        },
        hideUploadOverlay: function() {
            var overlay = document.getElementById('blockingOverlay');
            if (overlay) overlay.style.display = 'none';
            _currentOverlayId = null;
        }
    };

    window.DownloadManager = DownloadManager;
    window.IDCardApp = window.IDCardApp || {};
    window.IDCardApp.DownloadManager = DownloadManager;

    // Global shortcuts for upload overlay (convenience for vanilla JS upload code)
    window.showBlockingOverlay = DownloadManager.showUploadOverlay;
    window.updateBlockingOverlay = DownloadManager.updateUploadOverlay;
    window.hideBlockingOverlay = DownloadManager.hideUploadOverlay;

})();


/* ── js/init.js ── */

/**
 * Adarsh ID Cards - Main Initialization Module
 * 
 * This file serves as the entry point for the application's JavaScript.
 * It ensures all common modules are loaded and provides a global namespace.
 * 
 * Load Order:
 * 1. core/api.js       - CSRF token, API calls (ApiClient)
 * 2. core/toast.js     - Toast notifications (Toast)
 * 3. core/modal.js     - Modal/Drawer management (ModalManager)
 * 4. core/utils.js     - Image utilities, validation, helpers
 * 5. init.js           - This file (orchestration)
 * 
 * Then page-specific scripts:
 * - dashboard.js        - Dashboard page
 * - manage-staff.js     - Staff management page
 * - group-setting.js    - Group/Table settings page
 * - active-client.js    - Active clients page
 * - idcard-group.js     - ID card groups page
 * - settings.js         - User settings page
 * - idcard-actions-*.js - ID card actions modules
 * 
 * @module init
 * @version 1.0.0
 */

(function() {
    'use strict';

    // ==========================================
    // GLOBAL NAMESPACE
    // ==========================================

    /**
     * Global application namespace
     * All modules should attach to this namespace
     */
    window.Adarsh = window.Adarsh || {
        version: '2.0.0',
        debug: false,
        initialized: false,
        modules: {}
    };

    // ==========================================
    // MODULE VERIFICATION
    // ==========================================

    /**
     * Verify that all required common modules are loaded
     * @returns {Object} { loaded: string[], missing: string[] }
     */
    function verifyModules() {
        const requiredModules = [
            { name: 'Api', check: () => window.ApiClient || window.AdarshAjax },
            { name: 'Toast', check: () => window.Toast || window.AdarshToast || window.showToast },
            { name: 'Modal', check: () => window.ModalManager || window.AdarshModal },
            { name: 'Utils', check: () => window.AdarshUtils || window.escapeHtml }
        ];

        const loaded = [];
        const missing = [];

        requiredModules.forEach(module => {
            if (module.check()) {
                loaded.push(module.name);
            } else {
                missing.push(module.name);
            }
        });

        return { loaded, missing };
    }

    /**
     * Log module status to console (in debug mode)
     */
    function logModuleStatus() {
        const status = verifyModules();
        
        if (window.Adarsh.debug && status.missing.length > 0) {
            console.warn('Missing modules:', status.missing.join(', '));
        }

        return status;
    }

    // ==========================================
    // IDCARD APP NAMESPACE (Legacy support)
    // ==========================================

    /**
     * IDCardApp namespace for idcard-actions pages
     * Maintains backward compatibility with existing code
     */
    window.IDCardApp = window.IDCardApp || {
        tableId: null,
        currentStatus: 'pending',
        clientId: null,
        
        // Will be populated by idcard-actions-core.js
        getCSRFToken: function() {
            return window.getCSRFToken ? window.getCSRFToken() : '';
        },
        showToast: function(msg, type) {
            if (window.showToast) window.showToast(msg, type);
        },
        apiCall: function(url, method, data) {
            if (window.apiCall) return window.apiCall(url, method, data);
            return Promise.reject(new Error('apiCall not loaded'));
        }
    };

    // ==========================================
    // GLOBAL KEYBOARD SHORTCUTS
    // ==========================================

    /**
     * Initialize global keyboard shortcuts
     */
    function initKeyboardShortcuts() {
        // Escape key is handled by modal.js
        // C/V for sidebar is handled by sidebar.js
        
        document.addEventListener('keydown', function(e) {
            // Don't trigger if user is typing
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) {
                return;
            }

            // Ctrl/Cmd + F - Focus search (if exists)
            if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
                const searchInput = document.getElementById('searchInput') || 
                                   document.getElementById('search-input') ||
                                   document.querySelector('input[type="search"]');
                if (searchInput) {
                    e.preventDefault();
                    searchInput.focus();
                    searchInput.select();
                }
            }

            // Debug mode toggle: Ctrl+Shift+D
            if (e.ctrlKey && e.shiftKey && e.key === 'D') {
                window.Adarsh.debug = !window.Adarsh.debug;
                if (window.Adarsh.debug) {
                    logModuleStatus();
                }
            }
        });
    }

    // ==========================================
    // SEARCH CLEAR BUTTON (UNIVERSAL)
    // ==========================================

    /**
     * Wire up search clear buttons on any page.
     * Looks for .search-clear-btn inside .search-box and
     * pairs it with the sibling .search-input.
     * Skips pages where idcard-actions-search.js already handles it.
     */
    function initSearchClearButtons() {
        // If idcard-actions search module already loaded, skip
        if (typeof window.initSearchHandlers === 'function') return;

        document.querySelectorAll('.search-box').forEach(function(box) {
            const input = box.querySelector('.search-input');
            const clearBtn = box.querySelector('.search-clear-btn');
            if (!input || !clearBtn) return;

            function updateClear() {
                clearBtn.style.display = input.value.trim() ? 'flex' : 'none';
            }

            input.addEventListener('input', updateClear);

            clearBtn.addEventListener('click', function() {
                input.value = '';
                clearBtn.style.display = 'none';
                input.focus();
                // Fire input event so page-specific search logic re-runs
                input.dispatchEvent(new Event('input', { bubbles: true }));
            });

            // Initial state
            updateClear();
        });
    }

    // ==========================================
    // ERROR HANDLING
    // ==========================================

    /**
     * Error handling is managed by htmx-config.html (shows toasts on server errors)
     * and browser DevTools Console for JS errors.
     * No custom error monitoring JS needed.
     */
    function initErrorHandling() {
        // htmx-config.html handles HTMX errors (4xx/5xx → toast)
        // Browser DevTools Console catches JS errors natively
    }

    // ==========================================
    // INITIALIZATION
    // ==========================================

    /**
     * Main initialization function
     */
    function init() {
        if (window.Adarsh.initialized) return;

        // Log module status
        const status = logModuleStatus();

        // Initialize global keyboard shortcuts
        initKeyboardShortcuts();

        // Initialize search clear buttons (universal)
        initSearchClearButtons();

        // Initialize error handling
        initErrorHandling();

        // Dispatch ready event
        document.dispatchEvent(new CustomEvent('adarsh:ready', { 
            detail: { 
                version: window.Adarsh.version,
                modules: status.loaded
            } 
        }));

        window.Adarsh.initialized = true;
    }

    // ==========================================
    // AUTO-INITIALIZE
    // ==========================================

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // ==========================================
    // EXPOSE API
    // ==========================================

    window.Adarsh.verifyModules = verifyModules;
    window.Adarsh.logModuleStatus = logModuleStatus;
    window.Adarsh.init = init;

})();


/* ── js/global-search.js ── */

/**
 * Global Search Module (global-search.js)
 * 
 * Self-contained module that provides global ID card search via Ctrl+K.
 * Auto-injects the search button into the topbar and the search overlay into the body.
 * Works on any page — just include this script.
 */
(function () {
    'use strict';

    // ==========================================
    // AUTO-INJECT HTML
    // ==========================================

    function injectSearchButton() {
        // Don't inject if button already exists (backwards compat with dashboard pages)
        if (document.getElementById('globalSearchBtn')) return;

        // Only show the visible search button on dashboard pages.
        // Other pages still get Ctrl+K via the overlay + keyboard shortcut.
        const isDashboard = !!document.querySelector('.dashboard-content');
        if (!isDashboard) return;

        const topbar = document.querySelector('.topbar');
        if (!topbar) return;

        let navRight = topbar.querySelector('.nav-right');

        if (!navRight) {
            navRight = document.createElement('div');
            navRight.className = 'nav-right';
            topbar.appendChild(navRight);
        }

        const btn = document.createElement('button');
        btn.className = 'global-search-btn';
        btn.id = 'globalSearchBtn';
        btn.setAttribute('aria-label', 'Search ID cards (Ctrl+K)');
        btn.innerHTML = `
            <i class="fa-solid fa-magnifying-glass"></i>
            <span>Search ID cards...</span>
            <kbd>Ctrl+K</kbd>
        `;
        navRight.insertBefore(btn, navRight.firstChild);
    }

    function injectSearchOverlay() {
        // Don't inject if overlay already exists
        if (document.getElementById('globalSearchOverlay')) return;

        const overlay = document.createElement('div');
        overlay.className = 'global-search-overlay';
        overlay.id = 'globalSearchOverlay';
        overlay.innerHTML = `
            <div class="global-search-modal" role="dialog" aria-modal="true" aria-label="Search ID cards">
                <div class="global-search-header">
                    <div class="search-input-group">
                        <i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i>
                        <input type="text" id="globalSearchInput" placeholder="Search ID cards by name, address, mobile..." autocomplete="off" aria-label="Search ID cards">
                        <button class="clear-global-search" id="clearGlobalSearch" style="display: none;" aria-label="Clear search">
                            <i class="fa-solid fa-xmark" aria-hidden="true"></i>
                        </button>
                    </div>
                    <div class="search-filter-group">
                        <label for="globalSearchFilter">Filter:</label>
                        <select id="globalSearchFilter">
                            <option value="all">All Fields</option>
                            <option value="name">Name</option>
                            <option value="address">Address</option>
                            <option value="mobile">Mobile</option>
                        </select>
                    </div>
                    <button class="close-global-search" id="closeGlobalSearch" aria-label="Close search">
                        <i class="fa-solid fa-xmark" aria-hidden="true"></i>
                        <span>ESC</span>
                    </button>
                </div>
                <div class="global-search-body" id="globalSearchResults" aria-live="polite">
                    <div class="search-placeholder">
                        <i class="fa-solid fa-search"></i>
                        <p>Search across all ID cards</p>
                        <span>Enter at least 2 characters to search</span>
                    </div>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    }

    // ==========================================
    // SEARCH LOGIC
    // ==========================================

    let searchTimeout = null;

    function getEl(id) { return document.getElementById(id); }

    let _searchTriggerEl = null;

    function openGlobalSearch() {
        _searchTriggerEl = document.activeElement;
        const overlay = getEl('globalSearchOverlay');
        if (overlay) {
            overlay.classList.add('active');
            setTimeout(() => {
                const input = getEl('globalSearchInput');
                if (input) input.focus();
            }, 100);
        }
    }

    function closeGlobalSearch() {
        const overlay = getEl('globalSearchOverlay');
        const input = getEl('globalSearchInput');
        const clearBtn = getEl('clearGlobalSearch');
        const results = getEl('globalSearchResults');

        if (overlay) overlay.classList.remove('active');
        if (input) input.value = '';
        if (clearBtn) clearBtn.style.display = 'none';
        if (results) {
            results.innerHTML = `
                <div class="search-placeholder">
                    <i class="fa-solid fa-search"></i>
                    <p>Search across all ID cards</p>
                    <span>Enter at least 2 characters to search</span>
                </div>
            `;
        }
        // Restore focus to trigger element (a11y)
        if (_searchTriggerEl && typeof _searchTriggerEl.focus === 'function') {
            _searchTriggerEl.focus();
            _searchTriggerEl = null;
        }
    }

    function performSearch(query) {
        const filter = getEl('globalSearchFilter')?.value || 'all';
        const results = getEl('globalSearchResults');

        ApiClient.get(`/api/global-search/?q=${encodeURIComponent(query)}&filter=${filter}`)
            .then(data => {
                if (data.success) {
                    displayResults(data.results, query);
                } else if (results) {
                    const _esc = typeof escapeHtml === 'function' ? escapeHtml : (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
                    results.innerHTML = `
                        <div class="global-search-no-results">
                            <i class="fa-solid fa-exclamation-circle"></i>
                            <p>Error: ${_esc(data.message)}</p>
                        </div>
                    `;
                }
            })
            .catch(() => {
                if (results) {
                    results.innerHTML = `
                        <div class="global-search-no-results">
                            <i class="fa-solid fa-exclamation-circle"></i>
                            <p>Error searching. Please try again.</p>
                        </div>
                    `;
                }
            });
    }

    function displayResults(results, query) {
        const container = getEl('globalSearchResults');
        if (!container) return;

        const esc = typeof escapeHtml === 'function' ? escapeHtml : (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

        if (results.length === 0) {
            container.innerHTML = `
                <div class="global-search-no-results">
                    <i class="fa-solid fa-search"></i>
                    <p>No results found for "${esc(query)}"</p>
                </div>
            `;
            return;
        }

        let html = `<div class="global-search-results-header">${results.length} result${results.length > 1 ? 's' : ''} found</div>`;

        results.forEach(function (result) {
            // Use thumbnail for search results for faster loading
            let photoSrc = result.photo;
            let thumbSrc = null;
            if (result.photo && window.getThumbPath) {
                // Extract path from /media/... URL
                const mediaPath = result.photo.replace(/^\/media\//, '');
                const thumbPath = window.getThumbPath(mediaPath);
                if (thumbPath) {
                    thumbSrc = `/media/${thumbPath}`;
                }
            }
            
            let iconHtml;
            if (result.photo) {
                iconHtml = `<img src="${thumbSrc ? esc(thumbSrc) : esc(photoSrc)}" class="result-photo" alt="Photo" onerror="this.onerror=null; this.style.display='none'; this.nextElementSibling.style.display='flex';" ${thumbSrc ? `data-full="${esc(photoSrc)}"` : ''}>` +
                    `<div class="result-icon idcard" style="display:none"><i class="fa-solid fa-user"></i></div>`;
            } else {
                iconHtml = `<div class="result-icon idcard"><i class="fa-solid fa-user"></i></div>`;
            }

            html += `
                <div class="global-search-result-item" data-url="${esc(result.url)}">
                    ${iconHtml}
                    <div class="result-info">
                        <div class="result-title">${esc(result.title)}</div>
                        <div class="result-subtitle">${esc(result.subtitle)}</div>
                        <div class="result-match">Match: <strong>${esc(result.matched_field)}</strong> = "${esc(result.matched_value)}"</div>
                    </div>
                    <i class="fa-solid fa-chevron-right result-arrow"></i>
                </div>
            `;
        });

        container.innerHTML = html;

        container.querySelectorAll('.global-search-result-item').forEach(function (item) {
            item.addEventListener('click', function () {
                const url = this.getAttribute('data-url');
                if (url && url !== '#') {
                    this.innerHTML = `
                        <div class="result-icon"><i class="fa-solid fa-spinner fa-spin"></i></div>
                        <div class="result-info">
                            <div class="result-title">Loading...</div>
                            <div class="result-subtitle">Navigating to the record</div>
                        </div>
                    `;
                    this.style.pointerEvents = 'none';
                    window.location.href = url;
                }
            });
        });
    }

    // ==========================================
    // EVENT WIRING
    // ==========================================

    function initEvents() {
        const searchBtn = getEl('globalSearchBtn');
        const overlay = getEl('globalSearchOverlay');
        const input = getEl('globalSearchInput');
        const filter = getEl('globalSearchFilter');
        const clearBtn = getEl('clearGlobalSearch');
        const closeBtn = getEl('closeGlobalSearch');
        const resultsEl = getEl('globalSearchResults');

        // Button click
        if (searchBtn) {
            searchBtn.addEventListener('click', openGlobalSearch);
        }

        // Ctrl+K / Cmd+K
        document.addEventListener('keydown', function (e) {
            if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
                e.preventDefault();
                openGlobalSearch();
            }
            if (e.key === 'Escape' && overlay?.classList.contains('active')) {
                closeGlobalSearch();
            }
            // Focus trap inside search modal (a11y)
            if (e.key === 'Tab' && overlay?.classList.contains('active')) {
                const modal = overlay.querySelector('.global-search-modal');
                if (!modal) return;
                const focusable = modal.querySelectorAll('input:not([disabled]), button:not([disabled]):not([style*="display: none"]), select:not([disabled]), [tabindex]:not([tabindex="-1"])');
                if (!focusable.length) return;
                const first = focusable[0];
                const last = focusable[focusable.length - 1];
                if (e.shiftKey && document.activeElement === first) {
                    e.preventDefault(); last.focus();
                } else if (!e.shiftKey && document.activeElement === last) {
                    e.preventDefault(); first.focus();
                }
            }
        });

        // Close button
        if (closeBtn) {
            closeBtn.addEventListener('click', closeGlobalSearch);
        }

        // Click outside modal — disabled to prevent accidental closure
        // if (overlay) {
        //     overlay.addEventListener('click', function (e) {
        //         if (e.target === this) closeGlobalSearch();
        //     });
        // }

        // Clear search
        if (clearBtn) {
            clearBtn.addEventListener('click', function () {
                if (input) input.value = '';
                this.style.display = 'none';
                if (input) input.focus();
                if (resultsEl) {
                    resultsEl.innerHTML = `
                        <div class="search-placeholder">
                            <i class="fa-solid fa-search"></i>
                            <p>Search across all ID cards</p>
                            <span>Enter at least 2 characters to search</span>
                        </div>
                    `;
                }
            });
        }

        // Search input
        if (input) {
            input.addEventListener('input', function () {
                const query = this.value.trim();

                if (clearBtn) {
                    clearBtn.style.display = query.length > 0 ? 'flex' : 'none';
                }

                if (searchTimeout) clearTimeout(searchTimeout);

                if (query.length < 2) {
                    if (resultsEl) {
                        resultsEl.innerHTML = `
                            <div class="search-placeholder">
                                <i class="fa-solid fa-search"></i>
                                <p>${query.length === 0 ? 'Search across all ID cards' : 'Enter at least 2 characters'}</p>
                                <span>Enter at least 2 characters to search</span>
                            </div>
                        `;
                    }
                    return;
                }

                if (resultsEl) {
                    resultsEl.innerHTML = `
                        <div class="global-search-loading">
                            <i class="fa-solid fa-spinner fa-spin"></i>
                            <p>Searching...</p>
                        </div>
                    `;
                }

                searchTimeout = setTimeout(function () {
                    performSearch(query);
                }, 200);
            });
        }

        // Filter change
        if (filter) {
            filter.addEventListener('change', function () {
                const query = input?.value.trim();
                if (query && query.length >= 2) {
                    performSearch(query);
                }
            });
        }
    }

    // ==========================================
    // BOOTSTRAP
    // ==========================================

    function init() {
        injectSearchButton();
        injectSearchOverlay();
        initEvents();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // Expose for external use
    window.GlobalSearch = {
        open: openGlobalSearch,
        close: closeGlobalSearch
    };
})();


/* ── js/notification-bell.js ── */

/**
 * Notification Bell — Client-side JS
 * Handles: polling unread count, loading dropdown, mark read, mark all read
 * Include on any page that has the notification-bell.html partial.
 */

(function() {
  'use strict';

  let notifDropdownOpen = false;
  let notifData = [];
  const POLL_INTERVAL = 60000; // 60 seconds

  /* ── Init ── */
  document.addEventListener('DOMContentLoaded', function() {
    // Skip polling entirely when the bell partial is not rendered (e.g. admin users)
    if (!document.getElementById('notifWrapper')) return;

    pollUnreadCount();
    setInterval(pollUnreadCount, POLL_INTERVAL);

    // Close dropdown on outside click
    document.addEventListener('click', function(e) {
      const wrapper = document.getElementById('notifWrapper');
      if (wrapper && !wrapper.contains(e.target) && notifDropdownOpen) {
        closeNotifDropdown();
      }
    });

    // Escape key
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && notifDropdownOpen) closeNotifDropdown();
    });
  });

  /* ── Toggle ── */
  window.toggleNotifDropdown = function() {
    if (notifDropdownOpen) {
      closeNotifDropdown();
    } else {
      openNotifDropdown();
    }
  };

  function openNotifDropdown() {
    const dd = document.getElementById('notifDropdown');
    if (dd) {
      dd.classList.add('open');
      notifDropdownOpen = true;
      loadNotifications();
    }
  }

  function closeNotifDropdown() {
    const dd = document.getElementById('notifDropdown');
    if (dd) {
      dd.classList.remove('open');
      notifDropdownOpen = false;
    }
  }

  /* ── Poll Unread Count ── */
  async function pollUnreadCount() {
    try {
      const res = await fetch('/api/notifications/unread-count/');
      if (!res.ok) return;
      const data = await res.json();
      if (data.success) {
        updateBadge(data.unread_count);
      }
    } catch (err) {
      // Silently fail — non-critical
    }
  }

  function updateBadge(count) {
    const badge = document.getElementById('notifBadge');
    if (!badge) return;
    if (count > 0) {
      badge.classList.add('has-updates');
      badge.title = count + ' unread';
    } else {
      badge.classList.remove('has-updates');
      badge.title = '';
    }
  }

  /* ── Load Notifications ── */
  async function loadNotifications() {
    const list = document.getElementById('notifList');
    if (!list) return;

    try {
      const res = await fetch('/api/notifications/list/?limit=15');
      if (!res.ok) return;
      const data = await res.json();
      if (!data.success) return;

      notifData = data.notifications;
      updateBadge(data.unread_count);

      if (!notifData.length) {
        list.innerHTML = `<div class="notif-empty">
          <i class="fa-solid fa-bell-slash"></i>
          No notifications yet
        </div>`;
        return;
      }

      list.innerHTML = notifData.map(n => {
        const unreadClass = n.is_read ? '' : ' unread';
        const unreadDot = n.is_read ? '' : '<span class="notif-unread-dot"></span>';
        return `<div class="notif-item${unreadClass}" onclick="markNotificationRead(${n.id}, this)">
          <div class="notif-icon" style="background:${hexToRgba(n.priority_color, 0.12)};color:${n.priority_color};">
            <i class="fa-solid ${n.icon_class}"></i>
          </div>
          <div class="notif-body">
            <div class="notif-title">${escHtmlBell(n.title)}</div>
            <div class="notif-text">${escHtmlBell(n.message.length > 80 ? n.message.substring(0, 80) + '...' : n.message)}</div>
            <div class="notif-time">${n.time_ago} ago</div>
          </div>
          ${unreadDot}
        </div>`;
      }).join('');

    } catch (err) {
      console.error('Failed to load notifications:', err);
    }
  }

  /* ── Mark Read ── */
  window.markNotificationRead = async function(id, el) {
    try {
      await fetch(`/api/notifications/${id}/read/`, {
        method: 'POST',
        headers: { 'X-CSRFToken': getCsrfTokenBell() },
      });
      if (el) {
        el.classList.remove('unread');
        const dot = el.querySelector('.notif-unread-dot');
        if (dot) dot.remove();
      }
      pollUnreadCount();
    } catch (err) {
      // Non-critical
    }
  };

  /* ── Mark All Read ── */
  window.markAllNotificationsRead = async function() {
    try {
      await fetch('/api/notifications/mark-all-read/', {
        method: 'POST',
        headers: { 'X-CSRFToken': getCsrfTokenBell() },
      });
      // Refresh
      pollUnreadCount();
      loadNotifications();
    } catch (err) {
      console.error('Mark all read failed:', err);
    }
  };

  /* ── Helpers ── */
  // Use canonical getCSRFToken from core/api.js (exposed as window.getCSRFToken)
  function getCsrfTokenBell() {
    return (typeof window.getCSRFToken === 'function') ? window.getCSRFToken() : '';
  }

  function escHtmlBell(str) {
    const div = document.createElement('div');
    div.textContent = str || '';
    return div.innerHTML;
  }

  function hexToRgba(hex, alpha) {
    if (!hex || hex.charAt(0) !== '#') return 'rgba(102,126,234,' + alpha + ')';
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }

})();
